var EXTRA=[{dot:"green",j:"Journal of Orthopaedic Case Reports",h:"La RM riconosce bene le lesioni della radice meniscale, ma non sempre",v:"Studio prospettico monocentrico su lesioni sospette, con l'artroscopia come riferimento: buona accuratezza diagnostica ma piccolo campione a centro unico.",pmid:'42713124',doi:'10.13107/jocr.2026.v16.i09.8136',temi:["menisco", "root", "diagnostica per immagini"]},{dot:"green",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Il nuovo artrometro GNRB non sostituisce il KT1000 nel LCA",v:"Alta concordanza fra osservatori ma sensibilità diagnostica inferiore al KT1000 nell'identificare la lassità del legamento crociato anteriore.",pmid:'42712905',doi:'10.1002/ars2.70056',temi:["lca", "artrometria", "diagnostica"]},{dot:"gray",j:"Journal of Medical Internet Research",h:"La realtà estesa aiuta la riabilitazione dell'artrosi, meno quella dopo protesi",v:"Revisione sistematica: la riabilitazione digitale interattiva sembra utile nell'artrosi di ginocchio, l'evidenza dopo protesi resta più incerta e con pochi studi.",pmid:'42714169',doi:'10.2196/84753',temi:["realtà virtuale", "riabilitazione", "protesi totale"]},{dot:"gray",j:"The Journal of Knee Surgery",h:"In Cina, un'osteotomia su misura per chi vive in montagna",v:"Serie retrospettiva su una popolazione sottoposta a carichi biomeccanici intensi da lavoro agricolo di montagna: soddisfazione buona, ma nessun gruppo di confronto e soglia di allineamento solo esplorativa.",pmid:'42716087',doi:'10.1055/a-2949-2243',temi:["osteotomia", "mondo orientale", "popolazione ad alto carico"]},{dot:"gray",j:"A&A Practice",h:"Otto blocchi nervosi non battono l'infiltrazione locale nel dolore da protesi",v:"RCT su oltre duecento pazienti: nessuna differenza nel dolore percepito, ma consumo di morfina e degenza ridotti con la combinazione di blocchi nervosi.",pmid:'42714859',doi:'10.1213/XAA.0000000000002274',temi:["anestesia", "protesi totale", "analgesia"]},{dot:"green",j:"Journal of Orthopaedic Case Reports",h:"Il segnale RM del neolegamento del LCA si lega al recupero funzionale",v:"Studio prospettico monocentrico: minore intensità di segnale alla RM seriale si accompagna a punteggi funzionali migliori, ma il campione è piccolo e monocentrico.",pmid:'42713052',doi:'10.13107/jocr.2026.v16.i09.8138',temi:["lca", "risonanza magnetica", "guarigione dell'innesto"]},{dot:"green",j:"Journal of Orthopaedic Case Reports",h:"La riabilitazione accelerata dopo il LCA non compromette la stabilità",v:"Studio prospettico randomizzato su un piccolo campione: recupero funzionale comparabile fra protocollo accelerato e convenzionale, senza segnali di instabilità del ginocchio.",pmid:'42713062',doi:'10.13107/jocr.2026.v16.i09.8154',temi:["lca", "riabilitazione", "rientro allo sport"]},{dot:"green",j:"Journal of Orthopaedic Case Reports",h:"Una tecnica a doppio tunnel per l'avulsione della spina tibiale",v:"Serie prospettica senza gruppo di controllo su pazienti scheletricamente maturi: consolidamento radiologico raggiunto in tutti i casi, ma follow-up breve e nessun confronto con altre tecniche.",pmid:'42713333',doi:'10.13107/jocr.2026.v16.i09.8150',temi:["lca", "trauma", "tecnica chirurgica"]},{dot:"gray",j:"Journal of Exercise Rehabilitation",h:"Un programma neuromuscolare corregge un po' l'asse nel ginocchio varo",v:"RCT coreano su pazienti con ginocchio varo: l'esercizio neuromuscolare riduce il dolore e migliora l'allineamento radiografico rispetto al solo controllo, in un campione piccolo e solo femminile.",pmid:'42707335',doi:'10.12965/jer.2652470.235',temi:["genu varum", "riabilitazione", "allineamento"]},{dot:"gray",j:"Journal of Orthopaedic Surgery (Hong Kong)",h:"Chi salta i controlli dopo la protesi spesso sta meglio, non peggio",v:"Studio monocentrico retrospettivo: chi non si presenta ai controlli di routine dopo la protesi totale riferisce punteggi funzionali migliori e meno dolore di chi si presenta regolarmente.",pmid:'42712139',doi:'10.1177/10225536261459482',temi:["protesi totale", "follow-up", "esiti riferiti dal paziente"]},{dot:"gray",j:"Journal of Orthopaedic Case Reports",h:"La riparazione biologica del LCA recupera la forza muscolare più in fretta",v:"Studio comparativo su un piccolo campione: esiti clinici sovrapponibili all'innesto standard, con un recupero di forza del quadricipite e dell'hamstring più rapido nella riparazione con impalcatura biologica.",pmid:'42713275',doi:'10.13107/jocr.2026.v16.i09.8152',temi:["lca", "riparazione biologica", "tecnica emergente"]},{dot:"gray",j:"Journal of Controlled Release",h:"Perché i farmaci intra-articolari non arrivano dove serve, nella cartilagine",v:"Rassegna concettuale su un enzima (15-PGDH) e sulle barriere di trasporto nella cartilagine profonda: propone un modello sperimentale, senza dati clinici propri.",pmid:'42716128',doi:'10.1016/j.jconrel.2026.115338',temi:["cartilagine", "farmacologia", "ricerca traslazionale"]}];
var SCOPERTE=[{t:"Un plantare robotico per correggere il passo nell'artrosi di ginocchio",v:"Un piccolo studio giapponese descrive un dispositivo robotico indossabile, inserito nella scarpa, che corregge in tempo reale l'allineamento della caviglia durante il passo: riduce l'instabilità dell'appoggio in pazienti con artrosi del comparto mediale, ma è un'analisi esplorativa su sei pazienti, ben lontana dall'uso clinico.",pmid:'42656284',doi:'10.3389/frobt.2026.1898805',temi:["robotica indossabile", "riabilitazione del passo", "bioingegneria"]},{t:"A Pechino, il dolore da artrosi letto nei segnali del cervello",v:"Un gruppo di Pechino usa la magnetoencefalografia e modelli di intelligenza artificiale interpretabile per distinguere, dai segnali cerebrali, il dolore artrosico «neuropatico-simile» da quello nocicettivo puro: un'accuratezza solo moderata, ma un modo del tutto diverso di guardare al dolore da artrosi rispetto ai questionari abituali.",pmid:'42621580',doi:'10.2147/JPR.S622996',temi:["intelligenza artificiale", "neuroscienza del dolore", "mondo orientale"]},{t:"Idrogel ad alta viscosità: una nuova generazione di materiali per la cartilagine",v:"Una rassegna cinese descrive idrogel di nuova concezione capaci di dissipare le forze di carico e di riorganizzarsi dopo la deformazione, con l'obiettivo di rigenerare insieme cartilagine e osso subcondrale: stampa 3D/4D e intelligenza artificiale per ottimizzare i materiali sono indicate come prossima frontiera, ancora lontana dalla clinica.",pmid:'42714339',doi:'10.1039/d6bm00992a',temi:["biomateriali", "ingegneria tissutale", "cartilagine"]}];
var SOC={"1": {"video": "Una meta-analisi di 43 studi, oltre 17.000 pazienti, guarda al test più usato per decidere se un paziente può tornare allo sport dopo la ricostruzione del legamento crociato anteriore: il test del salto su una gamba. Superarlo con una simmetria di almeno il 90% si associa davvero a un rientro più probabile entro due anni. Ma lo stesso risultato, misurato nel salto triplo in distanza semplice, si associa a un rischio più alto — non più basso — di reinfortunio, anche se il margine è così piccolo da pesare poco nella pratica. Certezza dell'evidenza bassa in tutte le stime, nessuna sottoanalisi sul tipo di innesto: il messaggio pratico resta comunque netto — un singolo test motorio non basta a garantire che il ginocchio sia davvero al sicuro."}, "2": {"video": "Un panel di esperti cinesi di chirurgia protesica ha costruito, con un metodo strutturato di consenso, una guida completa per il percorso clinico della protesi di ginocchio personalizzata dentro un protocollo di recupero rapido: dalla valutazione prima dell'intervento fino alla riabilitazione a lungo termine. È un tipo di impianto diverso da quello robotico standard, quindi non si applica direttamente a ogni protesi — ma mostra quanto si stia lavorando, a livello di sistema, per rendere più uniforme e rapido il recupero dopo questo intervento."}, "3": {"video": "Un confronto su 259 protesi di ginocchio consecutive mette a paragone un robot chirurgico senza immagini preoperatorie con una guida laser molto più semplice, ed entrambi con la tecnica manuale classica. Sull'allineamento dell'intero arto, il robot non fa meglio della semplice guida laser — anche se entrambi fanno meglio della tecnica manuale. Solo nei casi di ginocchio molto storto il robot sembra avere un piccolo vantaggio, ma il gruppo studiato è piccolo e il segnale non si conferma in tutte le analisi. Il robot richiede anche più tempo in sala operatoria e costi più alti."}, "4": {"video": "Uno studio su quasi 150 ginocchia operate con tecnica robotica, conservando il legamento crociato posteriore, guarda a un dettaglio tecnico preciso: l'altezza della linea dove si incontrano femore e tibia, la cosiddetta linea articolare. Quando questa linea viene alzata troppo sul lato interno del ginocchio, il punteggio funzionale a un anno è significativamente peggiore rispetto a chi la mantiene stabile o la abbassa leggermente. È un promemoria intraoperatorio concreto per chi bilancia gli spazi articolari durante la protesi robotica con allineamento funzionale."}, "5": {"video": "Un timore tecnico frequente prima di un'osteotomia correttiva del ginocchio è che cambiare l'asse della tibia disturbi troppo l'articolazione tra rotula e femore. Uno studio giapponese su 45 ginocchia misura esattamente questo: la posizione della rotula cambia, ma in modo significativamente più piccolo dell'angolo di correzione dell'osso, e senza un impatto clinico rilevante — oltre il 70% dei pazienti supera la soglia di miglioramento clinicamente importante. Un piccolo peggioramento della cartilagine rotulea è statisticamente misurabile ma non si lega a un peggior risultato clinico."}, "6": {"video": "Uno studio turco-americano su 370 pazienti operati di protesi di ginocchio postero-stabilizzata, seguiti almeno quattro anni, guarda a un parametro molto discusso: l'inclinazione della tibia, o slope tibiale. Il risultato è netto: né la direzione né l'ampiezza del cambiamento di questo angolo, dentro i margini chirurgici normali, cambiano in modo rilevante quanto bene il paziente si sente dopo l'intervento. Il fattore che conta davvero, in tutte le analisi, è come stava il paziente prima di operarsi."}, "7": {"video": "Un registro britannico ha misurato, direttamente durante l'intervento con un sensore dedicato, quanto cambia il carico sulla rotula in 291 protesi di ginocchio. Il risultato: la variazione da un paziente all'altro è enorme, con un gruppo di pazienti che arriva a un aumento del carico superiore al 70% — più spesso nella protesi totale che nella sola resuperficializzazione della rotula. È un dato descrittivo, non ancora legato a un esito clinico, ma rafforza l'idea che il tracking della rotula vada controllato caso per caso, non solo con l'allineamento generale della gamba."}, "8": {"video": "Un piccolo studio americano su 39 pazienti operati di ricostruzione del legamento crociato anteriore prova un approccio diverso al rientro allo sport: non misurare soltanto la forza, ma allenare in tempo reale il modo di camminare. Con un segnale che aumenta leggermente il picco di forza a ogni passo su un tapis roulant strumentato, il carico complessivo cumulativo sulla gamba operata si riduce, senza aumentare lo stress sulle articolazioni del ginocchio. È una tecnica ancora sperimentale, su un piccolo gruppo di pazienti giovani, ma indica una strada diversa dalla sola misura della simmetria di forza."}};
var SOCV={"1": {"video": {"chir": ["Una meta-analisi di 43 studi, 17.350 pazienti, mette alla prova il test che usiamo più spesso per decidere il rientro allo sport dopo la ricostruzione del legamento crociato anteriore: il test del salto su una gamba. Superare la soglia abituale del 90% di simmetria — nel salto monopodalico in distanza, odds ratio 1,20, o nel salto triplo incrociato, odds ratio 1,18 — si associa davvero a un rientro allo sport più probabile entro due anni dall'intervento, in una casistica enorme per gli standard di questo campo.", "Ma lo stesso indice di simmetria, misurato nel salto triplo in distanza semplice, si associa a un rischio più alto, non più basso, di reinfortunio: odds ratio 1,05, intervallo di confidenza al 95% da 1,01 a 1,09. Un intervallo così stretto attorno all'unità pesa poco nella pratica clinica, anche se resta statisticamente significativo. L'associazione con il rientro è più forte quando oltre il 90% del campione ha un innesto hamstring, e in chi non ha lesioni meniscali associate: due condizioni che non descrivono automaticamente i tuoi operati.", "Gli autori dichiarano una certezza dell'evidenza bassa per tutte le stime, e non riportano alcuna sottoanalisi per tipo di innesto oltre al confronto hamstring contro il resto, né per l'aggiunta di un rinforzo extra-articolare laterale. Non tocca quindi il tuo innesto di retto femorale o quadricipite, né il LET che esegui su ogni paziente. Ma con quasi diciottomila pazienti in pooling, resta il segnale più solido finora: un singolo test motorio basato sulla distanza non è sufficiente, da solo, come criterio di rientro."], "misto": ["Il test del salto su una gamba è il modo più comune, oggi, per decidere se un paziente può tornare allo sport dopo l'operazione al legamento crociato anteriore. Una revisione molto ampia della letteratura scientifica — 43 studi, più di 17.000 pazienti in tutto — ha voluto controllare se questo test funzioni davvero: chi lo supera, raggiungendo almeno il 90% di simmetria fra le due gambe, torna effettivamente allo sport più spesso, entro due anni dall'operazione. Fin qui, il test sembra fare il suo lavoro.", "Il problema emerge quando si guarda al rischio di farsi male di nuovo, non solo al rientro. Nello stesso identico test, misurato in una delle sue varianti — il salto triplo in linea retta — chi supera la soglia del 90% ha un rischio leggermente più alto, non più basso, di reinfortunio. Il margine statistico è molto piccolo e pesa poco nella pratica di tutti i giorni, ma il messaggio resta chiaro: superare bene il test non equivale a essere protetti dal rifarsi male.", "Gli stessi autori dichiarano che la qualità complessiva delle prove raccolte è bassa, e lo studio non distingue, per esempio, il tipo di innesto usato nella ricostruzione né se sia stato eseguito anche un rinforzo laterale del ginocchio. Con oltre 17.000 pazienti analizzati insieme, però, è il segnale più forte raccolto finora su questo argomento: un solo test motorio, per quanto diffuso e ben conosciuto, non basta come unica misura per decidere che un ginocchio operato è davvero pronto a tornare in campo."], "pazienti": ["Dopo un'operazione al legamento crociato del ginocchio, uno dei test più usati per decidere quando un paziente può tornare a fare sport è il test del salto: si salta su una gamba sola e si confronta il risultato con quello dell'altra gamba, quella non operata. Un grande studio, che ha messo insieme i risultati di 43 ricerche diverse per oltre 17.000 pazienti, mostra che chi supera bene questo test — con un risultato molto simile fra le due gambe — riesce davvero a tornare allo sport più spesso.", "Ma lo stesso studio racconta anche un'altra parte della storia, altrettanto importante: superare bene il test del salto non garantisce che il ginocchio sia già al sicuro da un nuovo infortunio. In una delle versioni del test, chi otteneva un risultato molto simile fra le due gambe aveva addirittura un rischio leggermente più alto, non più basso, di farsi male di nuovo — anche se la differenza è piccola e non deve allarmare più del dovuto chi ha già superato bene questo passaggio della riabilitazione.", "Il messaggio pratico di questo studio, che ha analizzato più pazienti di quasi ogni altra ricerca fatta finora su questo argomento, è semplice da capire: il test del salto è utile, aiuta davvero a capire se un paziente è pronto a tornare a giocare, ma da solo non è sufficiente a garantire che il ginocchio non si farà più male. Per questo motivo il chirurgo e il fisioterapista valutano sempre più aspetti insieme, mai un solo numero isolato, prima di dare il via libera definitivo al rientro allo sport."]}, "linkedin": {"chir": ["SR&MA di 43 studi (17.350 pazienti) su hop test come predittore di RTS e reinfortunio dopo ACLR.", "LSI ≥90% in SLHD (OR 1,20; IC 95% 1,09-1,33) e TCHD (OR 1,18; IC 95% 1,02-1,36) associato a maggiore probabilità di RTS; LSI ≥90% in THD associato a maggiore reinfortunio (OR 1,05; IC 95% 1,01-1,09). Associazione con RTS più forte con >90% innesti hamstring (OR 1,64) e senza lesione meniscale (OR 1,39).", "Certezza GRADE bassa per tutte le stime; nessuna sottoanalisi per tipo di innesto o per LET. Il test del salto basato sulla distanza resta insufficiente come unico criterio di rientro."], "misto": ["Una meta-analisi molto ampia (43 studi, 17.350 pazienti) mette alla prova il test del salto usato per decidere il rientro allo sport dopo la ricostruzione del legamento crociato anteriore.", "Superare la soglia abituale del 90% di simmetria si associa a un rientro più probabile, ma la stessa soglia non predice in modo utile chi si reinfortunerà — anzi, in un test specifico il rischio risulta leggermente più alto.", "Evidenza di certezza bassa, ma il messaggio pratico è chiaro: un singolo test motorio non è sufficiente come criterio isolato di rientro allo sport."], "pazienti": ["Quanto dice davvero il test del salto sul rischio di rifarsi male al legamento crociato?", "Una grande revisione della letteratura mostra che superare questo test aiuta a prevedere il rientro allo sport, ma non protegge in modo dimostrabile dal reinfortunio.", "Un promemoria per chi si allena per rientrare: un solo test, per quanto diffuso, non basta a garantire la sicurezza del ginocchio."]}, "instagram": {"chir": ["Hop test e rientro allo sport dopo LCA: che cosa dice davvero la letteratura più ampia finora.", "43 studi, 17.350 pazienti: LSI ≥90% predice il rientro (OR 1,18-1,20) ma non protegge dal reinfortunio (OR 1,05, IC quasi all'unità).", "Evidenza a bassa certezza. Un test isolato basato sulla distanza non è un criterio di rientro sufficiente."], "misto": ["Il test del salto su una gamba: utile per il rientro, non per prevedere il reinfortunio.", "Una revisione enorme (43 studi, 17.000+ pazienti) lo confirma: superarlo aiuta a tornare allo sport, ma non garantisce che non ci si farà male di nuovo.", "Un test, non una garanzia: va usato insieme ad altre valutazioni del ginocchio."], "pazienti": ["Saltare bene su una gamba non vuol dire che il ginocchio sia già al sicuro al 100%.", "Un grande studio lo confirma: il test del salto aiuta a capire se puoi tornare allo sport, ma non basta a escludere un nuovo infortunio.", "Parlane con chi ti segue nella riabilitazione: il rientro si valuta nel suo insieme, non con un solo test."]}, "reel": {"chir": ["[testo: 43 STUDI · 17.350 PAZIENTI] Il test del salto predice il rientro, non il reinfortunio.", "LSI ≥90% → più rientro (OR 1,18-1,20). LSI ≥90% nel triplo semplice → più reinfortunio (OR 1,05).", "[testo: EVIDENZA BASSA] Un test isolato non basta come criterio di rientro."], "misto": ["[testo: IL TEST DEL SALTO, MESSO ALLA PROVA] 43 studi, 17.000+ pazienti dopo l'operazione al crociato.", "Superarlo aiuta a tornare allo sport — ma non protegge dal rifarsi male.", "[testo: UN TEST, NON UNA GARANZIA] Serve guardare il ginocchio nel suo insieme."], "pazienti": ["[testo: PUOI SALTARE BENE, MA SEI DAVVERO PRONTO?] Il test del salto su una gamba, spiegato.", "Chi lo supera torna più spesso a giocare come prima.", "[testo: MA NON BASTA] Non garantisce che il ginocchio sia già al sicuro."]}}, "2": {"video": {"chir": ["Un panel multidisciplinare di esperti cinesi di chirurgia protesica ha costruito, con un metodo Delphi modificato in due turni più una discussione online conclusiva, un consensus completo sul percorso clinico della protesi totale di ginocchio ad alta conformità — cioè personalizzata sull'anatomia individuale del paziente — dentro un protocollo di recupero rapido, l'ERAS. Il consenso è stato definito come un accordo di almeno l'85% fra gli esperti, distinto in forte, generale o moderato secondo la percentuale raggiunta su ciascuna raccomandazione.", "Il documento tocca ogni fase del percorso: la valutazione preoperatoria di precisione, l'imaging multimodale per pianificare l'intervento, i criteri di selezione del paziente candidato a un impianto personalizzato, il disegno e l'impianto accurato della componente su misura, la gestione perioperatoria, il controllo del dolore, la riabilitazione funzionale e il follow-up a lungo termine. L'abstract non riporta le percentuali di accordo raggiunte su ciascuna singola raccomandazione, ma descrive l'insieme come una guida pratica per standardizzare la pratica clinica cinese su questo tipo di protesi.", "È un documento di consensus, livello cinque nella scala dell'evidenza: non porta dati originali su una coorte di pazienti, ed è costruito sulla letteratura e sulla pratica clinica cinesi, la cui trasferibilità ad altri contesti sanitari non viene discussa. Soprattutto, la protesi «ad alta conformità personalizzata» descritta qui è una categoria di impianto diversa dal sistema robotico VELYS che utilizzi tu: resta comunque un esempio interessante di come si stia sistematizzando, su scala nazionale, il percorso perioperatorio attorno alla protesi di ginocchio."], "misto": ["In Cina, un gruppo di esperti di chirurgia protesica ha lavorato insieme, con un metodo strutturato di consenso, per scrivere una guida completa sul percorso clinico della protesi di ginocchio personalizzata — un impianto fatto su misura per l'anatomia di ciascun paziente — dentro un protocollo di recupero rapido dopo l'intervento. Il documento è nato da due turni di questionario fra gli esperti, seguiti da una discussione finale online, con l'obiettivo di arrivare a raccomandazioni condivise da applicare in tutto il paese.", "La guida copre davvero ogni fase del percorso: come valutare il paziente prima dell'intervento con le immagini più adatte, come scegliere chi è un buon candidato per un impianto personalizzato, come gestire il periodo post-operatorio, il controllo del dolore e la riabilitazione, fino ai controlli a lungo termine. Non riporta numeri precisi di quanti pazienti abbiano già seguito questo percorso: è pensata soprattutto per uniformare la pratica clinica dei chirurghi, non per dimostrare un risultato su una casistica.", "È importante sapere che riguarda un tipo particolare di protesi, personalizzata sull'anatomia di ogni paziente, diversa dal sistema robotico standard più diffuso altrove nel mondo. Non è quindi un documento che si applica direttamente a ogni protesi di ginocchio. Resta però un esempio interessante di come, in un grande paese come la Cina, si stia lavorando per rendere il percorso di recupero dopo questo intervento più uniforme, più rapido e più sicuro per tutti i pazienti."], "pazienti": ["In Cina, un gruppo di specialisti che si occupano di protesi di ginocchio ha deciso di mettersi d'accordo, tutti insieme, su come organizzare al meglio ogni fase di un intervento particolare: la protesi personalizzata, costruita su misura per l'anatomia di ciascun paziente. Hanno lavorato con un metodo di confronto strutturato, discutendo e rivedendo le proprie posizioni più volte, fino ad arrivare a una guida condivisa da usare in tutto il paese, con l'obiettivo di rendere il recupero dopo l'intervento più semplice e più rapido per i pazienti.", "La guida che ne è nata copre davvero tutte le fasi importanti: come si valuta il paziente prima dell'intervento, quali immagini servono per pianificare bene l'operazione, come gestire il periodo dopo l'intervento, come controllare il dolore, e come organizzare la riabilitazione fino ai controlli successivi nel tempo. È pensata per aiutare i medici a lavorare tutti nello stesso modo, con la stessa attenzione ai dettagli, indipendentemente dall'ospedale in cui il paziente viene operato.", "Va detto con chiarezza che questa guida riguarda un tipo particolare di protesi, fatta su misura per l'anatomia di ogni singolo paziente, diversa dal tipo di protesi robotica più diffusa in altri paesi, compresa la Svizzera. Non è quindi una novità che riguarda direttamente ogni paziente operato di protesi di ginocchio. Resta comunque un bell'esempio di come, lavorando insieme, un gruppo di specialisti possa rendere più uniforme e più sicuro un percorso di cura complesso come quello della protesi di ginocchio."]}, "linkedin": {"chir": ["Consensus Delphi modificato (panel multidisciplinare cinese) sul percorso ERAS per TKA ad alta conformità personalizzata.", "Raccomandazioni su valutazione preoperatoria, imaging multimodale, selezione del paziente, disegno dell'impianto, gestione perioperatoria, controllo del dolore, riabilitazione e follow-up a lungo termine. Consenso definito come accordo ≥85%.", "Livello V, nessun dato originale su pazienti. Impianto personalizzato ad alta conformità: categoria diversa dal sistema VELYS."], "misto": ["Come si costruisce un percorso di recupero rapido condiviso per la protesi di ginocchio personalizzata? Un panel di esperti cinesi lo ha messo per scritto.", "Il documento tocca ogni fase del percorso, dalla valutazione preoperatoria alla riabilitazione, con l'obiettivo di rendere la pratica più uniforme in tutto il paese.", "Non riguarda direttamente la protesi robotica standard, ma è un esempio interessante di come si stia sistematizzando il percorso perioperatorio attorno alla protesi di ginocchio."], "pazienti": ["Come rendere più rapido e sicuro il recupero dopo una protesi di ginocchio? Un gruppo di specialisti in Cina ha provato a metterlo per scritto.", "Il documento copre tutte le fasi, dalla preparazione all'intervento fino alla riabilitazione.", "Riguarda un tipo particolare di protesi su misura, diversa da quella robotica più diffusa qui — ma il principio del percorso organizzato vale in generale."]}, "instagram": {"chir": ["Cina: consensus Delphi sul percorso ERAS per la protesi di ginocchio personalizzata ad alta conformità.", "Dalla valutazione preoperatoria alla riabilitazione, un panel multidisciplinare definisce le tappe del percorso.", "Livello V, impianto diverso da VELYS: rilevante come modello organizzativo, non come indicazione diretta."], "misto": ["Come si costruisce, passo per passo, il percorso di recupero rapido dopo una protesi di ginocchio?", "Un gruppo di esperti cinesi lo ha definito con un metodo di consenso strutturato, dalla preparazione alla riabilitazione.", "Riguarda un impianto diverso da quello standard, ma il principio organizzativo vale comunque la pena di conoscerlo."], "pazienti": ["Un percorso condiviso per rendere più semplice il recupero dopo la protesi di ginocchio.", "Un gruppo di specialisti in Cina ha messo per scritto ogni fase, dalla preparazione alla riabilitazione.", "Riguarda un tipo particolare di protesi su misura, diversa da quella più diffusa qui."]}, "reel": {"chir": ["[testo: CINA · CONSENSUS DELPHI] Percorso ERAS per la protesi personalizzata ad alta conformità.", "Valutazione preop, imaging, impianto su misura, gestione del dolore, riabilitazione.", "[testo: LIVELLO V] Impianto diverso da VELYS: modello organizzativo, non indicazione diretta."], "misto": ["[testo: UN PERCORSO CONDIVISO] Come recuperare più in fretta dopo la protesi di ginocchio.", "Un gruppo di esperti cinesi definisce ogni fase, dalla preparazione alla riabilitazione.", "[testo: MODELLO, NON REGOLA UNIVERSALE] L'impianto qui è diverso da quello standard."], "pazienti": ["[testo: RECUPERO PIÙ RAPIDO, PASSO PER PASSO] Una guida condivisa per la protesi di ginocchio.", "Dalla preparazione all'intervento fino alla riabilitazione.", "[testo: UN TIPO PARTICOLARE DI PROTESI] Diversa da quella più diffusa qui."]}}, "3": {"video": {"chir": ["Un confronto propensity-matched su 259 protesi totali di ginocchio consecutive metti a paragone tre strategie di guida chirurgica: la tecnica manuale classica, la guida laser dell'asse meccanico e l'assistenza robotica senza immagini preoperatorie. L'errore assoluto medio dell'angolo anca-ginocchio-caviglia, la misura standard dell'allineamento dell'intero arto, è stato 2,20 gradi con la tecnica manuale, 1,19 gradi con la guida laser, e 0,95 gradi con il robot: una differenza che, presa da sola, suggerirebbe una scala di precisione crescente.", "Ma dopo l'abbinamento per punteggio di propensione, il quadro cambia: la guida laser riduce davvero l'errore rispetto alla tecnica manuale, di poco più di un grado, con una differenza statisticamente molto solida. Il confronto diretto fra il robot e la sola guida laser, invece, non mostra alcuna differenza significativa sull'errore dell'intero arto nella coorte completa: zero virgola zero tre gradi di differenza, un risultato che non permette di affermare che il robot senza immagini faccia davvero meglio di un semplice laser su questo esito.", "Solo in un piccolo sottogruppo di sedici coppie di ginocchia molto varate, il robot mostra un errore del componente femorale inferiore — ma questo vantaggio non resiste a un'analisi di sensibilità con un margine di abbinamento più stretto, segno che il campione è troppo piccolo per trarre conclusioni solide. Il robot richiede inoltre quattordici minuti in più di tempo operatorio e costi diretti più alti. Il sistema testato non è VELYS, ma appartiene alla stessa categoria di tecnologia senza immagini preoperatorie."], "misto": ["Un confronto diretto su 259 protesi di ginocchio metti a paragone tre modi diversi di guidare l'intervento: la tecnica manuale classica, una guida laser che segue l'asse della gamba, e un robot chirurgico che non usa immagini prese prima dell'operazione. Guardando solo ai numeri medi, l'errore di allineamento della gamba sembra diminuire passando dalla tecnica manuale al laser, e poi ancora dal laser al robot — un risultato che farebbe pensare a una scala chiara di precisione crescente con la tecnologia.", "Ma quando i ricercatori confrontano pazienti davvero simili tra loro, per rendere il paragone più corretto, il quadro cambia in modo importante. La guida laser fa davvero meglio della tecnica manuale, in modo netto e statisticamente solido. Il robot, però, non fa meglio della semplice guida laser sull'allineamento generale della gamba: la differenza tra i due, in questo confronto più rigoroso, è talmente piccola da non essere significativa. Un dato che sorprende, considerando quanto costa più il robot.", "Solo nei casi di ginocchio molto storto — un piccolo gruppo di appena sedici coppie di pazienti — il robot sembra avere un piccolo vantaggio tecnico su un singolo componente della protesi. Ma questo segnale è debole e non si conferma quando i ricercatori rendono l'analisi ancora più rigorosa: probabilmente è dovuto al caso, non a un vero vantaggio del robot. In compenso, operare con il robot richiede più tempo in sala operatoria e costa di più al paziente."], "pazienti": ["Sempre più spesso, per operare una protesi di ginocchio, si usano robot chirurgici sofisticati al posto della tecnica manuale tradizionale. Ma un robot più avanzato porta sempre un risultato migliore? Un confronto su oltre 250 protesi di ginocchio ha voluto rispondere a questa domanda, mettendo a paragone la tecnica manuale, una guida laser molto più semplice ed economica, e un robot chirurgico senza immagini preoperatorie, per vedere quale dei tre metodi allinea meglio la gamba dopo l'intervento.", "Il risultato più sorprendente riguarda proprio il confronto tra il robot e la semplice guida laser: quando si confrontano pazienti davvero simili tra loro, i due metodi ottengono un allineamento della gamba praticamente identico. Il laser, molto più semplice del robot, fa già bene il suo lavoro. Questo non vuol dire che il robot sia inutile, ma che la tecnologia più costosa non porta automaticamente un vantaggio misurabile per ogni tipo di ginocchio operato.", "Solo nei casi più difficili, quelli con una gamba molto storta prima dell'intervento, il robot potrebbe offrire un piccolo vantaggio in più — ma il gruppo di pazienti studiato in questa situazione era molto piccolo, e il segnale non è ancora del tutto confermato. Con il robot, inoltre, l'intervento richiede più tempo e costa di più. Un promemoria utile: la tecnologia più nuova non è sempre, automaticamente, quella che dà il risultato migliore per ogni paziente."]}, "linkedin": {"chir": ["Deformity-stratified comparative cohort, 259 TKA (110 manuale, 99 laser, 50 robot imageless).", "Errore HKA assoluto: 2,20° / 1,19° / 0,95° (p<0,001). Dopo propensity matching: laser vs manuale -1,01° (IC 95% -1,38/-0,64; p<0,001); robot vs laser -0,03° (p=0,612, ns). Sottogruppo varo grave (n=16 coppie): vantaggio femorale del robot non confermato in sensitivity analysis.", "Robot: +14,41 min tempo operatorio, OOP payment ratio 1,208. Sistema diverso da VELYS, ma stessa categoria (imageless)."], "misto": ["Nella protesi di ginocchio, un robot senza immagini preoperatorie fa davvero meglio di una semplice guida laser sull'allineamento della gamba?", "In un confronto su 259 interventi, la risposta è: non in modo dimostrabile, tranne un piccolo segnale nei casi di ginocchio molto storto, che però non si confirma in tutte le analisi statistiche.", "Il robot costa di più e richiede più tempo: un elemento da pesare nel bilancio complessivo della tecnologia scelta."], "pazienti": ["La tecnologia più sofisticata non è sempre quella che fa la differenza più grande.", "Un confronto su centinaia di protesi di ginocchio mostra che un robot senza immagini preoperatorie non batte, in modo dimostrabile, una guida laser molto più semplice sull'allineamento della gamba.", "Un promemoria utile quando si parla di innovazione in sala operatoria: non ogni tecnologia nuova porta un vantaggio misurabile per ogni paziente."]}, "instagram": {"chir": ["Robot imageless vs guida laser in TKA: allineamento HKA a confronto su 259 casi.", "Nessuna differenza dimostrabile fra robot e laser nella coorte completa; segnale debole nel varo grave, non confermato.", "Robot: più tempo operatorio, più costi. Sistema diverso da VELYS, stessa categoria imageless."], "misto": ["Robot o laser per la protesi di ginocchio? Un confronto diretto su oltre 250 casi.", "Sull'allineamento della gamba, i due metodi si comportano in modo simile — entrambi meglio della tecnica manuale.", "Il robot costa di più e richiede più tempo: da valutare il rapporto costo-beneficio."], "pazienti": ["Un robot per la protesi non garantisce sempre un risultato migliore di strumenti più semplici.", "In un confronto su centinaia di casi, robot e guida laser ottengono un allineamento della gamba simile.", "Solo per i casi più difficili il robot potrebbe fare un po' meglio, ma non è ancora certo."]}, "reel": {"chir": ["[testo: ROBOT vs LASER · 259 TKA] Allineamento HKA: nessuna differenza dimostrabile.", "Laser batte manuale (-1,01°). Robot = laser nella coorte completa.", "[testo: VARO GRAVE: SEGNALE DEBOLE] Non confermato nella sensitivity analysis."], "misto": ["[testo: ROBOT O LASER?] Un confronto su 259 protesi di ginocchio.", "Sull'allineamento della gamba, il risultato è quasi lo stesso.", "[testo: IL ROBOT COSTA PIÙ TEMPO E PIÙ SOLDI] Senza un vantaggio dimostrato."], "pazienti": ["[testo: TECNOLOGIA PIÙ AVANZATA = RISULTATO MIGLIORE?] Non sempre, mostra questo studio.", "Robot e guida laser semplice danno un allineamento della gamba simile.", "[testo: SOLO NEI CASI PIÙ DIFFICILI] Il robot potrebbe aiutare un po' di più."]}}, "4": {"video": {"chir": ["Uno studio retrospettivo monocentrico su 147 ginocchia operate di protesi totale primaria con conservazione del crociato posteriore, robot-assistita e con allineamento funzionale, guarda a un dettaglio tecnico molto preciso: l'altezza della linea articolare, cioè il punto in cui si incontrano femore e tibia dopo l'intervento, misurata con la tomografia computerizzata prima e dopo l'operazione, separatamente per il comparto mediale e per quello laterale del ginocchio.", "Il risultato principale riguarda il comparto mediale: quando la linea articolare viene elevata rispetto alla posizione nativa del paziente, il punteggio funzionale a un anno — il Forgotten Joint Score, che misura quanto il paziente si dimentica di avere una protesi — è significativamente peggiore rispetto a chi mantiene la linea stabile o la abbassa leggermente. La differenza media è di 28,5 punti, con una dimensione dell'effetto molto grande secondo il d di Cohen. I cambiamenti sul lato laterale, invece, non si associano in modo significativo all'esito a un anno.", "È uno studio retrospettivo, monocentrico, di livello tre, senza un gruppo di controllo operato con allineamento meccanico classico: il protocollo di allineamento funzionale del centro coreano che ha condotto lo studio non è necessariamente identico al tuo protocollo con VELYS. Ma protesi robot-assistita, conservazione del crociato e allineamento funzionale sono esattamente gli elementi della tua pratica quotidiana: un promemoria intraoperatorio concreto, da tenere presente quando si bilanciano gli spazi articolari durante l'intervento."], "misto": ["Uno studio coreano su quasi 150 ginocchie operate con tecnica robotica, mantenendo il legamento crociato posteriore del paziente, guarda a un dettaglio molto preciso dell'intervento: l'altezza della cosiddetta linea articolare, cioè il punto esatto in cui si incontrano l'osso della coscia e quello della gamba dopo aver posizionato la protesi. Questo dettaglio è stato misurato con una tomografia computerizzata sia prima che dopo l'operazione, separando il lato interno da quello esterno del ginocchio.", "Il risultato più importante riguarda il lato interno del ginocchio: quando questo punto viene alzato troppo rispetto alla posizione naturale del paziente, il punteggio che misura quanto bene il paziente si sente a un anno dall'intervento risulta significativamente peggiore, rispetto a chi mantiene questo punto stabile o lo abbassa leggermente. La differenza misurata è notevole, una delle più grandi viste in questo tipo di studi. Sul lato esterno del ginocchio, invece, questo stesso dettaglio non sembra influenzare il risultato a un anno.", "È uno studio condotto in un solo centro, senza un gruppo di pazienti operati con la tecnica classica per fare un confronto diretto: il protocollo usato in Corea potrebbe non essere identico a quello usato altrove. Ma riguarda esattamente il tipo di intervento — protesi robotica, con conservazione del legamento e allineamento personalizzato sulla funzione del paziente — che si pratica sempre più spesso anche qui. Un promemoria concreto: anche i dettagli tecnici più piccoli, durante l'intervento, possono pesare sul risultato a distanza di un anno."], "pazienti": ["Nella protesi di ginocchio robotica, ogni singolo dettaglio tecnico dell'intervento può contare per il risultato finale. Uno studio coreano ha guardato a un dettaglio molto specifico su quasi 150 pazienti operati: l'altezza di un punto preciso dell'articolazione, dove si incontrano l'osso della coscia e quello della gamba, misurata con una scansione prima e dopo l'operazione, separando il lato interno da quello esterno del ginocchio.", "Il risultato più interessante riguarda il lato interno: quando questo punto viene alzato troppo durante l'intervento rispetto alla posizione naturale del paziente, chi viene operato si sente significativamente peggio, un anno dopo, rispetto a chi ha questo punto mantenuto stabile o abbassato di poco. È una differenza importante, misurata con un questionario che chiede al paziente quanto si «dimentica» di avere un ginocchio artificiale nella vita di tutti i giorni. Sul lato esterno, invece, questo stesso dettaglio non sembra fare la stessa differenza.", "Questo studio riguarda un solo ospedale, senza un confronto diretto con la tecnica chirurgica classica, e usa un protocollo specifico che potrebbe non essere identico a quello usato dal tuo chirurgo. Ma il messaggio di fondo resta utile da conoscere: anche in un intervento moderno e assistito da un robot, la precisione di ogni singolo dettaglio tecnico durante l'operazione può influenzare davvero come ti sentirai un anno dopo essere stato operato."]}, "linkedin": {"chir": ["147 ginocchia, primary CR-TKA robot-assistita con functional alignment: associazione fra compartment-specific joint line (JL) change e PROM a 1 anno.", "Elevazione mediale della JL: FJS-12 significativamente peggiore (Δ media 28,5 punti; d=1,09). Depressione ben tollerata in entrambi i comparti; JL laterale non associata a PROM. Gap asymmetry comparabile fra sottogruppi.", "Retrospettivo, monocentrico, livello III, nessun braccio con allineamento meccanico classico. Protocollo di allineamento funzionale del centro, non necessariamente il tuo."], "misto": ["Nella protesi robotica con conservazione del crociato e allineamento funzionale, ogni millimetro di bilanciamento conta davvero?", "Uno studio su quasi 150 ginocchie mostra che alzare troppo la linea articolare sul lato interno peggiora in modo significativo il punteggio funzionale a un anno, mentre abbassarla leggermente è ben tollerato.", "Un promemoria intraoperatorio concreto per chi lavora con l'allineamento funzionale in chirurgia robotica del ginocchio."], "pazienti": ["A volte il dettaglio più piccolo di un intervento tecnico fa la differenza nel recupero.", "Uno studio su quasi 150 protesi robotiche di ginocchio mostra che un aggiustamento preciso durante l'intervento — l'altezza di un punto dell'articolazione — è legato al risultato riferito dal paziente un anno dopo.", "Un esempio di quanto la precisione chirurgica, anche in dettagli minimi, possa contare per il recupero."]}, "instagram": {"chir": ["Joint line change e PROM a 1 anno dopo CR-TKA robot-assistita con functional alignment: 147 ginocchia.", "Elevazione mediale della linea articolare → FJS-12 peggiore. Depressione ben tollerata.", "Retrospettivo, livello III: protocollo del centro, non necessariamente il tuo."], "misto": ["Nella protesi robotica, la linea articolare è un dettaglio che pesa davvero sul risultato.", "Alzarla troppo sul lato interno del ginocchio peggiora il punteggio funzionale a un anno.", "Un promemoria tecnico per chi bilancia gli spazi articolari durante l'intervento."], "pazienti": ["Anche i dettagli più piccoli di un intervento possono contare per il recupero.", "Uno studio mostra che un aggiustamento preciso durante la protesi robotica è legato a come ti senti un anno dopo.", "Un'informazione tecnica per il chirurgo, non qualcosa da gestire da parte del paziente."]}, "reel": {"chir": ["[testo: 147 GINOCCHIA · CR-TKA ROBOTICA] Joint line change e PROM a 1 anno.", "Elevazione mediale → FJS-12 peggiore (d=1,09).", "[testo: LIVELLO III] Protocollo del centro, non necessariamente il tuo."], "misto": ["[testo: UN MILLIMETRO CHE CONTA] La linea articolare nella protesi robotica.", "Alzarla troppo sul lato interno peggiora il risultato a un anno.", "[testo: PROMEMORIA INTRAOPERATORIO] Bilanciare bene gli spazi articolari."], "pazienti": ["[testo: I DETTAGLI PICCOLI CONTANO] Anche nella protesi robotica di ginocchio.", "Un aggiustamento preciso è legato a come ti senti un anno dopo.", "[testo: INFORMAZIONE PER IL CHIRURGO] Non richiede nulla da parte tua."]}}, "5": {"video": {"chir": ["Uno dei timori tecnici più frequenti prima di un'osteotomia tibiale alta ad apertura mediale è che correggere l'asse della tibia disturbi in modo rilevante l'articolazione femoro-rotulea. Uno studio giapponese su 45 ginocchia di 39 pazienti, con tomografia computerizzata dell'intero arto pre- e postoperatoria, ha misurato esattamente questo, con quattro angoli diversi: quello della cresta rotulea, del solco trocleare femorale, del quadricipite femorale e del tendine rotuleo.", "Il risultato principale è rassicurante: i cambiamenti dell'allineamento femoro-rotuleo sul piano coronale sono significativamente più piccoli dell'angolo di correzione osseo, che in media era di 9,3 gradi. La cresta rotulea, in particolare, cambia molto meno del quadricipite femorale — 3 gradi contro quasi 7. Solo il punteggio funzionale per le attività quotidiane peggiora leggermente con l'aumento dell'angolo del tendine rotuleo, e oltre il 70% dei pazienti raggiunge comunque un miglioramento clinicamente importante nei punteggi complessivi.", "Il grado di danno cartilagineo alla rotula, valutato in artroscopia, peggiora leggermente in modo statisticamente significativo, ma senza alcuna correlazione misurabile con i punteggi clinici del paziente. È una serie di casi retrospettiva, livello quattro, monocentrica, senza gruppo di controllo, e riguarda solo la tecnica ad apertura mediale. Per la tua pratica di osteotomie correttive resta comunque una rassicurazione operativa: il timore di disturbare eccessivamente la rotula correggendo l'asse tibiale non trova qui conferma clinica."], "misto": ["Chi opera un'osteotomia correttiva del ginocchio — l'intervento che cambia l'inclinazione della gamba per alleggerire un comparto usurato — si chiede spesso se questo cambiamento disturbi anche la rotula, l'osso davanti al ginocchio. Uno studio giapponese su 45 ginocchia ha misurato esattamente questo, confrontando immagini prese con la tomografia prima e dopo l'intervento, guardando a diversi punti di riferimento intorno alla rotula.", "La buona notizia è che la posizione della rotula cambia, sì, ma molto meno dell'angolo di correzione dell'osso della tibia: in media l'osso viene corretto di oltre nove gradi, mentre la rotula si sposta di pochi gradi. I punteggi funzionali dei pazienti migliorano nella grande maggioranza dei casi, in modo clinicamente rilevante, cioè percepibile davvero nella vita di tutti i giorni. Solo un punteggio specifico, quello per le attività quotidiane, peggiora leggermente in chi ha un cambiamento maggiore in uno degli angoli misurati.", "Un piccolo peggioramento della cartilagine della rotula si osserva anch'esso, in modo statisticamente misurabile, ma senza alcun legame evidente con come si sente il paziente. È uno studio piccolo, su un solo tipo di osteotomia, senza un gruppo di confronto diretto: le conclusioni vanno prese con la giusta prudenza. Ma resta un segnale rassicurante per chi teme che correggere l'asse della gamba possa fare più danni che benefici alla rotula."], "pazienti": ["Quando si corregge l'inclinazione della gamba con un intervento chiamato osteotomia — spesso proposto a chi ha un'usura precoce di un solo lato del ginocchio — un dubbio frequente è: questo cambierà anche la posizione della rotula, l'ossicino davanti al ginocchio? Uno studio giapponese su 45 ginocchia ha voluto rispondere a questa domanda con precisione, misurando la posizione della rotula prima e dopo l'intervento con immagini dettagliate.", "La risposta è rassicurante: la posizione della rotula cambia, ma molto meno di quanto cambia l'osso della gamba durante la correzione. La maggior parte dei pazienti, oltre sette su dieci, migliora in modo importante e percepibile nella vita di tutti i giorni. Solo in una piccola parte dei pazienti si osserva un leggero peggioramento della cartilagine della rotula, ma questo non sembra legato a come il paziente si sente dopo l'intervento.", "Questo studio è piccolo, riguarda un solo tipo di correzione chirurgica e non ha un gruppo di pazienti non operati per fare un confronto diretto: va quindi letto con la giusta cautela. Ma è comunque una buona notizia per chi si sta preparando a questo tipo di intervento, e teme che correggere l'asse della gamba possa portare problemi inaspettati alla rotula."]}, "linkedin": {"chir": ["Retrospective case series, 45 knees/39 patients, medial open-wedge HTO: coronal PFJ alignment change vs correction angle.", "PFJ indicators significantly smaller than correction angle (patellar ridge 3,0° vs quadriceps femoris 6,8°; p<0,001); KOOS ADL decreases with patellar tendon angle (r=-0,333); >70% achieve MCID; ICRS grade worsens slightly (p=0,004), no clinical correlation.", "Level IV, single-centre, no control arm, medial open-wedge only."], "misto": ["Correggere l'asse della gamba con un'osteotomia sposta anche la rotula: ma quanto, e con quali conseguenze cliniche?", "Uno studio giapponese su 45 ginocchia risponde: il cambiamento è significativamente più piccolo dell'angolo di correzione osseo, e l'impatto clinico resta trascurabile.", "Un dato utile per chi pratica osteotomie correttive del ginocchio, con il limite di una serie piccola e senza confronto."], "pazienti": ["Un dubbio tecnico frequente su un intervento di correzione dell'asse del ginocchio trova una risposta rassicurante.", "Uno studio giapponese mostra che la rotula si sposta molto meno di quanto ci si aspetterebbe dopo questo tipo di intervento.", "Una buona notizia con il limite di uno studio piccolo, su una sola tecnica di correzione."]}, "instagram": {"chir": ["Osteotomia tibiale alta e allineamento femoro-rotuleo: 45 ginocchia, cambiamento minore della correzione.", "ICRS rotuleo peggiora leggermente ma senza correlazione clinica; MCID KOOS raggiunta in oltre 70%.", "Livello IV, serie monocentrica, senza gruppo di controllo."], "misto": ["L'osteotomia correttiva del ginocchio disturba la rotula? Meno di quanto si pensi.", "Uno studio giapponese lo confirma: la rotula si sposta, ma molto meno dell'angolo di correzione ossea.", "Serie piccola, senza confronto, ma un segnale rassicurante per questa tecnica."], "pazienti": ["Un dubbio frequente sull'osteotomia del ginocchio trova una risposta rassicurante.", "La rotula si sposta molto meno di quanto ci si aspetterebbe dopo l'intervento.", "Buona notizia, con il limite di uno studio piccolo su una sola tecnica."]}, "reel": {"chir": ["[testo: 45 GINOCCHIA · HTO MEDIALE] Cambiamento PFJ minore della correzione osteotomica.", "Cresta rotulea 3,0° vs correzione 9,3°. Impatto clinico trascurabile.", "[testo: LIVELLO IV] Serie retrospettiva, senza gruppo di controllo."], "misto": ["[testo: L'OSTEOTOMIA DISTURBA LA ROTULA?] Meno di quanto si pensi, mostra questo studio.", "La rotula si sposta molto meno dell'angolo di correzione dell'osso.", "[testo: SEGNALE RASSICURANTE] Serie piccola, una sola tecnica di osteotomia."], "pazienti": ["[testo: UN DUBBIO TECNICO, RISOLTO] La rotula dopo l'osteotomia del ginocchio.", "Si sposta molto meno di quanto ci si aspetterebbe.", "[testo: BUONA NOTIZIA] Con il limite di uno studio piccolo."]}}, "6": {"video": {"chir": ["Uno studio retrospettivo turco-americano su 370 pazienti operati di protesi totale di ginocchio postero-stabilizzata, con un unico disegno di impianto e un follow-up minimo di 48 mesi, guarda a un parametro molto discusso in chirurgia protesica: lo slope tibiale posteriore, l'inclinazione della componente tibiale sul piano sagittale, misurata su radiografie laterali standardizzate da due osservatori indipendenti in cieco.", "Il risultato è netto: né la direzione del cambiamento dello slope — un aumento, una diminuzione o nessun cambiamento — né la sua ampiezza si associano in modo statisticamente significativo al dolore postoperatorio, agli esiti funzionali riferiti dal paziente o al miglioramento clinico complessivo. Tutti i confronti restano con un valore p superiore a 0,05. Un aumento dello slope si associa solo a un modesto guadagno di flessione del ginocchio, mezzo grado per ogni grado di slope aggiunto, ma questo guadagno di movimento non si traduce in un punteggio funzionale migliore.", "In tutte le analisi statistiche condotte, il predittore più forte del risultato dopo l'intervento resta lo stato funzionale del paziente prima di operarsi, non il valore dello slope tibiale raggiunto in sala operatoria. È uno studio monocentrico, livello tre, con un solo disegno di impianto postero-stabilizzato — diverso dal disegno con conservazione del crociato che potresti usare con il tuo sistema VELYS — ma il messaggio pratico resta comunque utile: entro i margini chirurgici normali, piccole variazioni dello slope non decidono da sole il risultato finale."], "misto": ["Nella protesi di ginocchio, un parametro tecnico molto discusso è lo slope tibiale, cioè l'inclinazione con cui viene posizionata la parte di protesi sulla tibia. Uno studio su 370 pazienti operati, seguiti per almeno quattro anni, ha voluto capire quanto questo dettaglio tecnico influenzi davvero il risultato che il paziente percepisce dopo l'intervento, misurando con precisione l'angolo prima e dopo l'operazione con due osservatori indipendenti.", "Il risultato è chiaro e in un certo senso sorprendente: piccole differenze in questo angolo, dentro i margini considerati normali dai chirurghi, non cambiano in modo importante quanto bene il paziente si sente dopo l'intervento — non sul dolore, non sulla funzione, non sul miglioramento complessivo. Un aumento dell'inclinazione si associa solo a una leggera maggiore capacità di piegare il ginocchio, ma questo piccolo guadagno di movimento non si traduce in un miglioramento percepito dal paziente.", "Il fattore che conta davvero, in tutte le analisi fatte dai ricercatori, è come stava il paziente prima dell'intervento, non il valore esatto di questo angolo tecnico raggiunto durante l'operazione. È uno studio su un solo tipo di protesi, in un solo centro: un limite da tenere presente. Ma il messaggio pratico resta valido: non tutti i dettagli tecnici di un intervento pesano allo stesso modo sul risultato finale percepito dal paziente."], "pazienti": ["Durante una protesi di ginocchio, il chirurgo deve posizionare con precisione ogni singola componente, inclusa l'inclinazione della parte metallica che appoggia sulla tibia — un dettaglio tecnico chiamato slope tibiale. Uno studio su 370 pazienti operati, seguiti per anni, ha voluto capire se piccole differenze in questo angolo cambino davvero come il paziente si sente dopo l'intervento.", "La risposta è rassicurante per chi si preoccupa dei dettagli tecnici: piccole variazioni di questo angolo, dentro i margini considerati normali, non fanno una differenza importante nel dolore, nella funzione o nel benessere generale del paziente dopo l'intervento. Solo la capacità di piegare un po' di più il ginocchio sembra leggermente collegata a questo angolo, ma senza tradursi in un vero miglioramento percepito.", "Quello che conta davvero, secondo questo studio, è come stava il paziente prima di operarsi, non il valore esatto di un singolo angolo tecnico raggiunto durante l'intervento. È un dato rassicurante: significa che, entro i limiti normali della chirurgia, piccole variazioni tecniche non dovrebbero far preoccupare chi si sta preparando a questo intervento, o chi è già stato operato."]}, "linkedin": {"chir": ["Single-centre retrospective cohort, 370 primary cemented PS-TKA, min. 48-month follow-up: effect of PTS change on functional outcomes.", "Neither direction nor magnitude of PTS change associated with pain, function or overall clinical improvement (all p>0,05). PTS increase associated with modest ROM gain (0,53°/degree; p<0,001) without translating into PROM benefit. Preoperative functional status: strongest predictor across all analyses.", "Level III, single implant design (PS), single centre. Not the CR design you may use with VELYS."], "misto": ["Quanto conta davvero lo slope tibiale nel risultato di una protesi di ginocchio?", "Uno studio su 370 pazienti, seguiti almeno 4 anni, risponde: entro i margini chirurgici normali, poco o nulla — conta molto più lo stato funzionale di partenza del paziente.", "Un dato utile per non sovrastimare il peso di un singolo parametro tecnico nel giudizio complessivo sul risultato."], "pazienti": ["Non tutti i dettagli tecnici di un intervento pesano allo stesso modo sul risultato finale.", "Uno studio su centinaia di pazienti operati di protesi di ginocchio lo dimostra per un parametro molto discusso, l'inclinazione della tibia.", "Quello che conta di più resta come stava il paziente prima dell'intervento."]}, "instagram": {"chir": ["Slope tibiale posteriore e PS-TKA: 370 pazienti, nessuna associazione clinicamente rilevante con gli esiti.", "Stato funzionale preoperatorio: predittore più forte in tutte le analisi.", "Livello III, disegno postero-stabilizzato, diverso dal disegno CR."], "misto": ["Lo slope tibiale conta davvero nel risultato della protesi di ginocchio? Meno di quanto si pensi.", "Uno studio su 370 pazienti lo confirma: entro i margini normali, piccole variazioni non cambiano il risultato.", "Conta più lo stato funzionale del paziente prima dell'intervento."], "pazienti": ["Non tutti i dettagli tecnici di un intervento contano allo stesso modo.", "Uno studio su centinaia di pazienti lo dimostra per un parametro molto discusso della protesi.", "Quello che conta di più è come stavi prima dell'operazione."]}, "reel": {"chir": ["[testo: 370 PS-TKA · 48+ MESI] Slope tibiale e risultato funzionale: nessun legame rilevante.", "Stato funzionale preoperatorio = predittore più forte.", "[testo: LIVELLO III] Disegno postero-stabilizzato, non CR."], "misto": ["[testo: LO SLOPE TIBIALE CONTA DAVVERO?] Meno di quanto si pensi, mostra questo studio.", "370 pazienti, 4+ anni: piccole variazioni non cambiano il risultato.", "[testo: CONTA PIÙ LO STATO DI PARTENZA] Del paziente prima dell'intervento."], "pazienti": ["[testo: NON TUTTI I DETTAGLI PESANO UGUALE] Nella protesi di ginocchio.", "Uno studio su centinaia di pazienti lo dimostra.", "[testo: CONTA COME STAVI PRIMA] Dell'operazione."]}}, "7": {"video": {"chir": ["Un registro osservazionale britannico ha raccolto, in modo prospettico, misurazioni intraoperatorie dirette del carico femoro-rotuleo — con un dispositivo dedicato chiamato Quadsense — in 291 interventi di protesi di ginocchio, prima e dopo l'impianto delle componenti di prova, distinguendo i comparti mediale, laterale, superiore e inferiore dell'articolazione femoro-rotulea.", "Il dato più rilevante è la variabilità individuale: la maggior parte dei casi mostra piccoli cambiamenti percentuali di carico, ma un sottogruppo distinto di pazienti supera un aumento cumulativo di oltre il settanta per cento. La protesi totale mostra una distribuzione più ampia e una frequenza osservata più alta di grandi aumenti, rispetto alla sola resuperficializzazione femoro-rotulea isolata. L'analisi per sistema di impianto, limitata alla protesi totale, mostra differenze descrittive fra le diverse coorti di impianto studiate, con alcuni sistemi che mostrano una frequenza più alta di grandi aumenti di carico.", "È un disegno di registro puramente descrittivo, senza alcun test di ipotesi prespecificato né aggiustamento per fattori di confondimento: le differenze fra impianti restano descrittive, non causali. Gli specifici sistemi di impianto confrontati non sono nominati nell'abstract, quindi non sappiamo se il tuo VELYS o l'impianto ATTUNE siano fra questi. Resta un richiamo concreto a controllare sempre il tracking rotuleo caso per caso durante l'intervento, non solo l'allineamento generale dell'arto."], "misto": ["Durante una protesi di ginocchio, la rotula subisce un cambiamento di carico che nessuno, finora, aveva misurato in modo così diretto e su una scala così ampia. Un registro britannico ha usato un sensore dedicato per misurare esattamente questo, durante 291 interventi di protesi, confrontando il carico prima e dopo l'impianto della protesi, in diverse zone dell'articolazione fra rotula e femore.", "Il risultato più sorprendente è la variabilità: da un paziente all'altro, il cambiamento di carico sulla rotula varia moltissimo. Nella maggior parte dei casi il cambiamento è piccolo, ma in un gruppo distinto di pazienti il carico aumenta di oltre il settanta per cento rispetto a prima dell'intervento — un aumento notevole. Questo succede più spesso nella protesi totale di ginocchio che nella sola sostituzione della sola superficie della rotula, e sembra variare anche in base al tipo esatto di impianto usato.", "È uno studio descrittivo, che non collega ancora questi cambiamenti a un vero problema clinico futuro per il paziente, e non nomina i sistemi di impianto confrontati. Ma il messaggio pratico è utile: il carico sulla rotula durante una protesi di ginocchio non è affatto uguale per tutti i pazienti, e vale la pena che il chirurgo lo controlli con attenzione caso per caso, non solo guardando all'allineamento generale della gamba."], "pazienti": ["Quando viene fatta una protesi di ginocchio, non tutto va allo stesso identico modo per ogni paziente: anche il carico che la protesi mette sulla rotula, l'osso davanti al ginocchio, può variare molto da persona a persona. Uno studio inglese ha misurato esattamente questo, durante quasi trecento interventi, usando uno strumento apposito applicato durante l'operazione.", "Il risultato principale è che la variazione da paziente a paziente è davvero ampia: alcuni pazienti hanno un cambiamento minimo di carico sulla rotula, mentre altri arrivano a un aumento importante, oltre il settanta per cento rispetto a prima dell'intervento. Questo succede un po' più spesso con la protesi totale di ginocchio rispetto a interventi più piccoli e limitati alla sola rotula.", "Non sappiamo ancora, da questo studio, se questa differenza di carico porti davvero a un problema per il paziente più avanti nel tempo: è un dato descrittivo, non una dimostrazione. Ma è un'informazione tecnica preziosa per il chirurgo, che può usarla per prestare più attenzione, durante l'intervento, a come la rotula si muove e a quanto carico riceve in ogni singolo caso."]}, "linkedin": {"chir": ["Observational registry, 291 knee replacement procedures, prospective intraoperative patellofemoral load measurement (Quadsense), compartment-specific.", "Marked inter-individual variability; distinct subset with cumulative load increase >+70%; TKR shows broader distribution of large increases vs isolated PFJR; lateral/superior compartments account for most redistribution.", "No pre-specified hypothesis testing, no confounder adjustment: descriptive associations only. Implant systems not named."], "misto": ["Quanto pesa davvero la protesi sulla rotula? Un registro britannico lo ha misurato direttamente, durante centinaia di interventi.", "Il risultato: una variabilità individuale enorme, con alcuni pazienti che arrivano a un aumento di carico superiore al 70%.", "Un dato ancora descrittivo, ma un ulteriore richiamo a controllare il tracking della rotula caso per caso, non solo l'allineamento generale."], "pazienti": ["Anche in un intervento standardizzato come la protesi di ginocchio, ogni paziente è un caso a sé.", "Uno studio ha misurato direttamente, durante centinaia di interventi, quanto varia il carico sulla rotula: la differenza da persona a persona è risultata molto ampia.", "Un'informazione tecnica per il chirurgo, non qualcosa che richiede un'azione da parte del paziente."]}, "instagram": {"chir": ["Carico femoro-rotuleo intraoperatorio: 291 protesi, variabilità marcata fra pazienti e tra sistemi.", "Sottogruppo con aumento cumulativo >+70%, più frequente in TKR che in PFJR isolata.", "Descrittivo, nessun aggiustamento per confondenti."], "misto": ["Quanto varia il carico sulla rotula durante la protesi? Molto più di quanto si pensi.", "Un registro britannico lo misura direttamente: alcuni pazienti superano un aumento del 70%.", "Un motivo in più per controllare il tracking rotuleo caso per caso."], "pazienti": ["Ogni protesi di ginocchio è un caso a sé, anche per il carico sulla rotula.", "Uno studio l'ha misurato direttamente durante centinaia di interventi.", "Un'informazione tecnica per il chirurgo, non un'azione per il paziente."]}, "reel": {"chir": ["[testo: 291 PROTESI · CARICO ROTULEO INTRAOPERATORIO] Variabilità marcata tra pazienti.", "Sottogruppo: aumento cumulativo >+70%, più in TKR che in PFJR.", "[testo: DESCRITTIVO] Nessun aggiustamento per confondenti."], "misto": ["[testo: QUANTO PESA LA PROTESI SULLA ROTULA?] Un registro lo misura direttamente.", "Alcuni pazienti superano un aumento di carico del 70%.", "[testo: TRACKING ROTULEO] Da controllare caso per caso."], "pazienti": ["[testo: OGNI PROTESI È UN CASO A SÉ] Anche per il carico sulla rotula.", "Uno studio l'ha misurato durante centinaia di interventi.", "[testo: INFORMAZIONE TECNICA] Per il chirurgo, non per il paziente."]}}, "8": {"video": {"chir": ["Uno studio sperimentale su 39 pazienti, 6-12 mesi dopo la ricostruzione primaria del legamento crociato anteriore, ha testato un biofeedback del cammino in tempo reale su tapis roulant strumentato: due condizioni, una che segnala un aumento del cinque per cento del peso corporeo nel picco di forza di reazione verticale al terreno, l'altra che segnala una diminuzione della stessa entità, per tremila passi ciascuna, a velocità autoselezionata dal paziente.", "L'impulso di forza di reazione al terreno in fase di appoggio è risultato significativamente più basso durante il carico dinamico rispetto al carico sostenuto — zero virgola cinquantuno contro zero virgola cinquantaquattro peso corporeo per secondi, con un valore p di zero virgola zero tre. Non sono state osservate differenze statisticamente significative negli impulsi assoluti dei momenti articolari al ginocchio, né sul piano sagittale né su quello frontale, suggerendo che l'aumento del picco di forza non si traduce in un aumento del carico complessivo articolare.", "Non esiste, a oggi, una soglia clinicamente rilevante nota per la differenza di impulso osservata: la sua importanza clinica resta da stabilire con studi futuri. La popolazione è giovane, in media ventuno anni, e a breve distanza dalla ricostruzione, sei-dodici mesi; l'abstract non riporta nemmeno il tipo di innesto usato dai partecipanti. Resta comunque un primo strumento tecnico interessante, da seguire, per modulare il carico del cammino oltre la sola misura della simmetria di forza nella riabilitazione tardiva dopo la ricostruzione del crociato."], "misto": ["Nella riabilitazione dopo l'operazione al legamento crociato del ginocchio, di solito si misura soprattutto la forza muscolare recuperata. Un piccolo studio americano ha provato un approccio diverso, su 39 pazienti operati sei-dodici mesi prima: allenare il modo di camminare in tempo reale, usando un segnale che indica al paziente quanta forza sta usando a ogni passo, camminando su un tapis roulant speciale collegato a sensori di precisione.", "Il risultato principale è che, quando il segnale invita il paziente ad aumentare leggermente la forza a ogni passo, il carico complessivo cumulativo sulla gamba operata durante tutta la camminata risulta più basso rispetto a quando il segnale invita a diminuire questa forza. Allo stesso tempo, non è cambiato in modo significativo lo stress sulle articolazioni del ginocchio in nessuna delle due direzioni misurate — un dettaglio importante, perché significa che aumentare la forza al passo non sovraccarica automaticamente il ginocchio.", "Non sappiamo ancora se questa piccola differenza faccia davvero una differenza clinica per il paziente nel lungo periodo: nessuna soglia di riferimento è oggi conosciuta per interpretarla. Lo studio riguarda pazienti giovani, in media ventuno anni, a pochi mesi dall'operazione, e non specifica nemmeno il tipo di innesto usato. Ma è una direzione di ricerca interessante, oltre la semplice misura della forza muscolare, per la riabilitazione tardiva dopo l'operazione al crociato."], "pazienti": ["Dopo un'operazione al legamento crociato del ginocchio, la riabilitazione si concentra di solito sul recuperare la forza dei muscoli della gamba. Un piccolo studio americano ha provato invece a lavorare su un aspetto diverso: il modo di camminare. A 39 pazienti operati da sei a dodici mesi è stato chiesto di camminare su un tapis roulant speciale, mentre un segnale in tempo reale indicava loro quanta forza stavano usando a ogni passo con la gamba operata.", "Quando il segnale invitava i pazienti ad aumentare un po' la forza a ogni passo, il carico complessivo sulla gamba operata, calcolato su tutta la camminata, risultava più basso — un risultato che può sembrare controintuitivo, ma che i ricercatori spiegano con il modo in cui il corpo distribuisce il peso durante il passo. Allo stesso tempo, questo non ha aumentato lo stress sulle articolazioni del ginocchio, un segnale incoraggiante per la sicurezza di questo tipo di allenamento del cammino.", "È ancora una tecnica sperimentale, provata su un gruppo piccolo di pazienti giovani, non ancora parte della riabilitazione standard che si trova oggi negli studi di fisioterapia. Non sappiamo nemmeno se porti, nel tempo, a un rischio più basso di problemi al ginocchio. Ma indica una strada di ricerca interessante: anche il modo in cui si cammina, non solo la forza dei muscoli, potrebbe diventare uno strumento utile nella riabilitazione dopo questo tipo di intervento."]}, "linkedin": {"chir": ["Experimental study, 39 patients 6-12 months post-ACLR: real-time gait biofeedback (RTGBF), dynamic vs sustained loading.", "vGRF stance-phase impulse significantly lower with dynamic vs sustained loading (0,51±0,07 vs 0,54±0,06 BW·s; p=0,03); no significant difference in absolute sagittal- or frontal-plane knee-moment impulses.", "No established clinically meaningful threshold for the observed vGRF impulse difference; young population, graft type not reported."], "misto": ["Si può insegnare a camminare in un modo più protettivo dopo la ricostruzione del legamento crociato, guidando il paziente in tempo reale?", "Un piccolo studio americano suggerisce di sì: un segnale che aumenta leggermente la forza a ogni passo riduce il carico complessivo sulla gamba operata, senza aumentare lo stress articolare.", "Un risultato preliminare, su un campione piccolo e giovane, ma una direzione di ricerca interessante oltre la sola misura della simmetria di forza."], "pazienti": ["La riabilitazione dopo un intervento al ginocchio può includere anche il modo in cui si cammina, non solo esercizi di forza.", "Un piccolo studio mostra che un segnale in tempo reale durante la camminata può aiutare a ridurre il carico complessivo sulla gamba operata.", "È ancora una tecnica sperimentale, non parte della riabilitazione standard oggi."]}, "instagram": {"chir": ["Biofeedback del cammino in tempo reale dopo ACLR: riduce l'impulso vGRF senza aumentare i momenti articolari.", "39 pazienti, 6-12 mesi post-ricostruzione: risultato preliminare.", "Nessuna soglia clinica nota; popolazione giovane."], "misto": ["Camminare in modo diverso, guidati da un segnale in tempo reale, dopo l'operazione al crociato.", "Un piccolo studio: riduce il carico complessivo sulla gamba operata senza stressare il ginocchio.", "Tecnica ancora sperimentale, su un gruppo piccolo di pazienti giovani."], "pazienti": ["Anche il modo di camminare può fare parte della riabilitazione dopo l'operazione al crociato.", "Un piccolo studio mostra che un segnale in tempo reale può alleggerire il carico sulla gamba operata.", "Non è ancora parte della riabilitazione standard, ma una direzione promettente."]}, "reel": {"chir": ["[testo: 39 PAZIENTI · POST-ACLR] Biofeedback del cammino in tempo reale.", "Impulso vGRF ↓ (p=0,03). Momenti articolari: nessuna differenza.", "[testo: PRELIMINARE] Nessuna soglia clinica nota."], "misto": ["[testo: CAMMINARE DIVERSO, GUIDATI IN TEMPO REALE] Dopo l'operazione al crociato.", "Riduce il carico sulla gamba operata, senza stressare il ginocchio.", "[testo: STUDIO PRELIMINARE] Su un piccolo gruppo di giovani pazienti."], "pazienti": ["[testo: ANCHE COME CAMMINI PUÒ AIUTARE] Dopo l'operazione al crociato.", "Un segnale in tempo reale può alleggerire la gamba operata.", "[testo: TECNICA ANCORA SPERIMENTALE] Non è riabilitazione standard oggi."]}}};
var TAGS={"1": {"linkedin": "#ACLReconstruction #ReturnToSport #SportsMedicine", "instagram": "#LCA #RientroAlloSport #TestDelSalto #Ginocchio #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #Ricerca #Riabilitazione", "kw": "test del salto LCA, rientro sport crociato anteriore"}, "2": {"linkedin": "#TotalKneeArthroplasty #EnhancedRecovery #Orthopaedics", "instagram": "#ProtesiGinocchio #RecuperoRapido #ERAS #Ortopedia #ChirurgiaOrtopedica #Cina #Ricerca #Innovazione #SaluteArticolare", "kw": "protesi ginocchio personalizzata Cina, percorso ERAS protesi"}, "3": {"linkedin": "#RoboticSurgery #TotalKneeArthroplasty #Orthopaedics", "instagram": "#ChirurgiaRobotica #ProtesiGinocchio #Allineamento #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #Corea #Innovazione", "kw": "robot protesi ginocchio confronto laser, chirurgia robotica allineamento"}, "4": {"linkedin": "#RoboticTKA #JointLine #Orthopaedics", "instagram": "#ProtesiGinocchio #ChirurgiaRobotica #LineaArticolare #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #AllineamentoFunzionale #SaluteArticolare", "kw": "protesi robotica linea articolare, allineamento funzionale protesi ginocchio"}, "5": {"linkedin": "#HighTibialOsteotomy #KneeAlignment #Orthopaedics", "instagram": "#Osteotomia #Rotula #GinocchioVaro #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #CorrezioneAsse #SaluteArticolare", "kw": "osteotomia ginocchio rotula, correzione asse gamba femoro-rotulea"}, "6": {"linkedin": "#TotalKneeArthroplasty #TibialSlope #Orthopaedics", "instagram": "#ProtesiGinocchio #SlopeTibiale #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteArticolare #RecuperoFunzionale #ChirurgiaProtesica", "kw": "protesi ginocchio slope tibiale, protesi postero-stabilizzata risultati"}, "7": {"linkedin": "#PatellofemoralJoint #TotalKneeArthroplasty #Orthopaedics", "instagram": "#ProtesiGinocchio #Rotula #TrackingRotuleo #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteArticolare #ChirurgiaProtesica", "kw": "protesi ginocchio carico rotula, tracking femoro-rotuleo protesi"}, "8": {"linkedin": "#ACLRehabilitation #Biofeedback #SportsMedicine", "instagram": "#LCA #Biofeedback #RiabilitazioneCammino #Ginocchio #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #Ricerca #RitornoAlloSport", "kw": "biofeedback cammino LCA, riabilitazione carico ginocchio crociato"}};
var NLB={"1": {"prof": ["Il test del salto prevede il rientro ma non il reinfortunio dopo il LCA", "Una meta-analisi di 43 studi e 17.350 pazienti mostra che superare la soglia del 90% di simmetria nel salto monopodalico o nel salto triplo incrociato si associa a un rientro allo sport più probabile entro due anni.", "Lo stesso indice di simmetria nel salto triplo in distanza semplice si associa però a un rischio più alto, non più basso, di reinfortunio: un intervallo di confidenza molto vicino all'unità, e una certezza dell'evidenza definita bassa dagli stessi autori."], "mix": ["Il test del salto dice se puoi tornare a giocare, ma non se ti farai male di nuovo", "Una revisione di 43 studi, oltre 17.000 pazienti, guarda al test più usato per decidere il rientro allo sport dopo l'operazione al legamento crociato: superarlo si associa a un rientro più probabile.", "Ma lo stesso risultato non basta a prevedere chi si reinfortunerà: la relazione con il rientro è più solida di quella con il reinfortunio, e la certezza dell'evidenza resta bassa."], "paz": ["Saltare bene su una gamba non garantisce che il ginocchio sia davvero al sicuro", "Un grande studio ha analizzato il test del salto su una gamba, usato spesso per decidere quando un paziente può tornare allo sport dopo l'operazione al legamento crociato: chi lo supera torna più spesso a giocare.", "Ma superarlo non vuol dire essere protetti dal rischio di farsi male di nuovo: è un test utile, non una garanzia, e va usato insieme ad altre valutazioni."], "kw": "test del salto LCA rientro sport, reinfortunio crociato anteriore"}, "2": {"prof": ["Un consensus cinese per il percorso di recupero rapido nella protesi personalizzata", "Un panel di esperti cinesi costruisce con metodo Delphi un consensus sul percorso clinico della protesi di ginocchio ad alta conformità (personalizzata) dentro un protocollo di recupero rapido (ERAS), dalla valutazione preoperatoria alla riabilitazione.", "È un impianto personalizzato, categoria diversa dal sistema robotico che utilizzi: resta un esempio di come si stia standardizzando il percorso perioperatorio attorno alla protesi di ginocchio."], "mix": ["Come si organizza, in Cina, il recupero rapido dopo una protesi di ginocchio su misura", "Un gruppo di esperti cinesi ha messo a punto, con un metodo strutturato di consenso, un percorso clinico completo per la protesi di ginocchio personalizzata dentro un protocollo di recupero rapido.", "Riguarda un tipo di impianto diverso da quello robotico standard: è utile soprattutto come esempio di organizzazione del percorso, non come indicazione diretta sulla tua protesi."], "paz": ["In Cina nasce una guida condivisa per il recupero rapido dopo la protesi di ginocchio", "Un gruppo di esperti cinesi ha messo per scritto, insieme, come organizzare al meglio tutte le fasi della protesi di ginocchio personalizzata: prima dell'intervento, durante il ricovero e nella riabilitazione.", "È una guida pensata per un tipo particolare di protesi su misura, diversa da quella robotica standard: mostra comunque quanto si stia lavorando per rendere il recupero più rapido e uniforme."], "kw": "protesi ginocchio personalizzata Cina, recupero rapido dopo protesi"}, "3": {"prof": ["Robot senza immagini contro guida laser: nella protesi l'allineamento non cambia", "In 259 protesi consecutive, l'assistenza robotica senza immagini preoperatorie non riduce ulteriormente l'errore di allineamento dell'intero arto rispetto alla sola guida laser, se non in un piccolo sottogruppo di ginocchia molto varate.", "Il vantaggio del robot nel sottogruppo di varo grave non resiste all'analisi di sensibilità con un campione più piccolo: un segnale debole, non una dimostrazione, e il sistema testato non è quello che usi tu."], "mix": ["Robot o semplice laser: per l'allineamento della protesi non cambia molto", "Un confronto su oltre 250 protesi di ginocchio mette a paragone un robot senza immagini preoperatorie con una guida laser molto più semplice: sull'allineamento dell'intero arto, il risultato è sostanzialmente lo stesso.", "Solo nei casi di ginocchio molto storto il robot sembra fare un po' meglio, ma il numero di casi è piccolo e il segnale non si confirma in tutte le analisi."], "paz": ["Un robot per la protesi non significa automaticamente un risultato migliore", "Uno studio ha confrontato due modi di guidare l'intervento di protesi di ginocchio: uno con un robot che non usa immagini prima dell'operazione, uno con un semplice laser. Il risultato sull'allineamento della gamba è simile.", "Solo nei casi di gamba molto storta il robot potrebbe aiutare un po' di più, ma il numero di pazienti studiati in quel gruppo è piccolo."], "kw": "robot protesi ginocchio confronto, chirurgia robotica allineamento gamba"}, "4": {"prof": ["Nella protesi robotica, alzare la linea articolare mediale peggiora il risultato", "In 147 ginocchia operate con conservazione del crociato e allineamento funzionale, un innalzamento della linea articolare nel comparto mediale si associa a un punteggio funzionale a un anno significativamente peggiore.", "Studio retrospettivo monocentrico, senza gruppo di controllo con allineamento meccanico classico: il centro e il protocollo di allineamento funzionale non sono necessariamente identici al tuo."], "mix": ["Un dettaglio della protesi robotica che pesa sul risultato a un anno", "Uno studio su quasi 150 ginocchie operate con un robot che conserva il legamento crociato mostra che alzare troppo, su un lato del ginocchio, la linea dove si incontrano femore e tibia peggiora il risultato riferito dal paziente un anno dopo.", "È un dettaglio tecnico intraoperatorio, non qualcosa che riguarda la scelta di operarsi o no: aiuta il chirurgo a bilanciare meglio l'articolazione durante l'intervento."], "paz": ["Un piccolo dettaglio tecnico della protesi robotica può cambiare come ti senti dopo un anno", "Uno studio su quasi 150 ginocchia operate con tecnica robotica ha trovato che un piccolo aggiustamento tecnico durante l'intervento — quanto si alza un punto preciso dell'articolazione — è legato a come il paziente si sente un anno dopo.", "È un'informazione tecnica che riguarda il chirurgo durante l'operazione, non qualcosa che il paziente deve fare o decidere."], "kw": "protesi ginocchio robotica linea articolare, protesi allineamento funzionale esiti"}, "5": {"prof": ["Dopo l'osteotomia, la rotula si sposta meno dell'osso che la regge", "In 45 ginocchia operate di osteotomia tibiale alta ad apertura mediale, l'allineamento coronale dell'articolazione femoro-rotulea cambia significativamente meno dell'angolo di correzione osseo, con un impatto clinico e cartilagineo trascurabile.", "Serie di casi retrospettiva di livello IV, senza gruppo di controllo, solo per la tecnica ad apertura mediale: un piccolo peggioramento cartilagineo rotuleo statisticamente significativo non si traduce in una correlazione clinica misurabile."], "mix": ["Correggere l'asse della gamba non stravolge la rotula, mostra un nuovo studio", "Un lavoro giapponese su 45 ginocchia operate di osteotomia correttiva ha misurato quanto cambia la posizione della rotula dopo l'intervento: cambia, ma molto meno dell'angolo di correzione dell'osso, e senza un impatto clinico rilevante.", "È uno studio piccolo, senza un gruppo di confronto, che riguarda una sola tecnica di osteotomia: un segnale rassicurante più che una regola definitiva."], "paz": ["Correggere l'asse del ginocchio non disturba la rotula quanto si potrebbe temere", "Uno studio giapponese ha guardato che cosa succede alla rotula quando si corregge l'asse della gamba con un'osteotomia: la rotula si sposta, ma molto meno di quanto ci si aspetterebbe, e senza conseguenze cliniche rilevanti.", "È un dato rassicurante su un timore tecnico specifico, non una garanzia valida per ogni caso: lo studio è piccolo e riguarda una sola tecnica di correzione."], "kw": "osteotomia ginocchio rotula allineamento, correzione asse gamba femoro-rotulea"}, "6": {"prof": ["Nella protesi, piccoli cambi di slope tibiale non cambiano il risultato", "In 370 protesi postero-stabilizzate con almeno 4 anni di follow-up, né la direzione né l'ampiezza del cambiamento di slope tibiale posteriore si associano in modo clinicamente rilevante al risultato funzionale.", "Studio monocentrico su un solo disegno di impianto postero-stabilizzato, diverso dal disegno con conservazione del crociato che potresti usare: l'analisi copre solo gli intervalli chirurgici accettati, non gli errori più estremi."], "mix": ["Nella protesi di ginocchio, piccole variazioni dell'inclinazione tibiale non decidono il risultato", "Uno studio su 370 pazienti operati di protesi, seguiti almeno 4 anni, mostra che piccole differenze nell'inclinazione della tibia dopo l'intervento non cambiano in modo rilevante quanto bene il paziente si sente.", "Conta molto più lo stato funzionale del paziente prima dell'intervento: un promemoria che non tutti i dettagli tecnici pesano allo stesso modo sul risultato finale."], "paz": ["Un piccolo dettaglio tecnico della protesi non decide da solo come ti sentirai", "Uno studio su centinaia di pazienti operati di protesi di ginocchio, seguiti per anni, mostra che piccole differenze in un angolo tecnico dell'intervento non cambiano in modo importante il risultato finale.", "Quello che conta di più è come stava il paziente prima dell'intervento: un motivo in più per non farsi condizionare da piccoli dettagli tecnici quando si valuta un risultato."], "kw": "protesi ginocchio slope tibiale, protesi postero-stabilizzata risultato funzionale"}, "7": {"prof": ["Il carico sulla rotula durante la protesi varia molto da un impianto all'altro", "Un registro di 291 protesi con misurazione intraoperatoria diretta del carico femoro-rotuleo mostra una variabilità individuale marcata, con un sottogruppo che supera un aumento cumulativo del 70%, più frequente nella protesi totale.", "Disegno di registro puramente descrittivo, senza test di ipotesi prespecificato né aggiustamento per confondenti: i sistemi di impianto confrontati non sono nominati nell'abstract."], "mix": ["Quanto pesa la protesi sulla rotula? Molto più di quanto si creda, e in modo diverso caso per caso", "Un registro britannico ha misurato direttamente, durante l'intervento, quanto cambia il carico sulla rotula in 291 protesi di ginocchio: la variazione da paziente a paziente è grande, e in alcuni casi molto elevata.", "È un dato descrittivo, che non prova ancora un legame con complicanze cliniche future: mostra però quanto sia importante controllare il tracking della rotula caso per caso, non solo l'allineamento generale."], "paz": ["Ogni protesi di ginocchio è un po' diversa: anche il carico sulla rotula cambia da persona a persona", "Uno studio ha misurato, durante centinaia di interventi di protesi di ginocchio, quanto cambia il carico sulla rotula: la variazione da un paziente all'altro è risultata molto ampia.", "È un'informazione tecnica utile al chirurgo per affinare l'intervento caso per caso; non richiede nulla di diverso da parte del paziente."], "kw": "protesi ginocchio carico rotula, tracking rotuleo protesi totale"}, "8": {"prof": ["Un biofeedback in tempo reale riduce il carico cumulativo dopo il LCA", "In 39 pazienti 6-12 mesi dopo la ricostruzione del LCA, un biofeedback in tempo reale che aumenta il picco di forza di reazione al terreno durante il cammino riduce il carico cumulativo sull'arto operato, senza aumentare i momenti articolari.", "Nessuna soglia clinicamente rilevante nota per la differenza di impulso osservata: popolazione giovane, a breve distanza dalla ricostruzione, e senza dati sul tipo di innesto usato dai partecipanti."], "mix": ["Un allenamento del passo guidato in tempo reale può alleggerire il carico dopo il crociato", "Uno studio americano su 39 pazienti operati di ricostruzione del legamento crociato mostra che un segnale in tempo reale, durante la camminata su tapis roulant, può ridurre il carico complessivo sulla gamba operata.", "È un risultato preliminare su un piccolo gruppo di pazienti giovani: non si sa ancora se questo si traduca in un rischio più basso di problemi futuri al ginocchio."], "paz": ["Camminare in un certo modo, guidati da un segnale in tempo reale, potrebbe alleggerire il ginocchio operato", "Un piccolo studio ha provato a insegnare ai pazienti operati al legamento crociato, tramite un segnale durante la camminata su un tapis roulant, a caricare la gamba in un modo che riduce lo stress complessivo sul ginocchio.", "È una tecnica ancora sperimentale, provata su pochi pazienti giovani: non è oggi parte della riabilitazione standard."], "kw": "biofeedback cammino LCA, riabilitazione crociato carico ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Journal of Sports Science & Medicine",h:"Il test del salto prevede il rientro ma non il reinfortunio del LCA",v:"Una meta-analisi di 43 studi (17.350 pazienti) mostra che superare la soglia del 90% di simmetria nel test del salto monopodalico si associa a un rientro allo sport più probabile, ma predice poco il rischio di reinfortunio del legamento crociato anteriore.",ax:"Liu, Sun, Cao et al.",date:"set 2026",meta:"revisione sistematica e meta-analisi di 43 studi, 17.350 partecipanti · [II]",pmid:'42713242',doi:'10.52082/jssm.2026.772',journal:"Journal of Sports Science & Medicine",authors:"Liu Y, Sun Y, Cao M, Wang D, Wang L, Fong DTP, Yung PS, Qiu J",design:"Revisione sistematica e meta-analisi (PubMed, SPORTDiscus, MEDLINE, Web of Science) di studi su pazienti con ricostruzione primaria unilaterale del legamento crociato anteriore (LCA) che riportano test del salto (hop test) e almeno uno tra rientro allo sport (RTS) o reinfortunio; rischio di bias con Newcastle-Ottawa Scale modificata, certezza dell'evidenza con GRADE modificato.",pop:"43 studi, 17.350 partecipanti; 24 studi sul rientro allo sport, 21 sul reinfortunio.",results:"Raggiungere un indice di simmetria (LSI) ≥90% nel salto monopodalico in distanza (OR 1,20; IC 95% 1,09-1,33) o nel salto triplo incrociato in distanza (OR 1,18; IC 95% 1,02-1,36) si associa a una maggiore probabilità di rientro allo sport entro due anni; lo stesso indice ≥90% nel salto triplo in distanza semplice si associa invece a un rischio più alto, non più basso, di reinfortunio (OR 1,05; IC 95% 1,01-1,09). L'associazione con il rientro è più forte negli studi con oltre il 90% di innesti hamstring (OR 1,64; IC 95% 1,13-2,39) e in chi non ha lesioni meniscali associate (OR 1,39; IC 95% 1,14-1,69). Certezza dell'evidenza bassa in tutte le stime.",concl:"Gli autori concludono che il test del salto, da solo e basato sulla sola distanza, predice in modo utile il rientro allo sport ma non è sufficiente a prevedere il rischio di reinfortunio, specie fuori dal sottogruppo hamstring senza lesione meniscale.",limits:"Certezza GRADE bassa per tutte le stime pooled · eterogeneità dichiarata fra criteri di rientro e protocolli di hop test nei 43 studi · nessuna sottoanalisi per innesto oltre al confronto hamstring/altro, né per l'aggiunta di un rinforzo extra-articolare laterale.",perte:"Il dato più diretto finora sulla tensione T3: anche con 17.350 pazienti in pooling, l'indice di simmetria del salto — la misura più usata per decidere il rientro — resta associato al rientro ma non protegge in modo dimostrabile dal reinfortunio. Non tocca il tuo innesto né il LET che esegui sempre, ma rafforza da una base molto più ampia il punto centrale della tensione: un criterio motorio isolato non basta."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Chinese Journal of Reparative and Reconstructive Surgery",h:"Un consensus cinese unifica il percorso ERAS per la protesi personalizzata",v:"Un panel multidisciplinare di esperti cinesi di chirurgia protesica costruisce, con metodo Delphi modificato, un consensus sul percorso clinico della protesi totale di ginocchio ad alta conformità (personalizzata) dentro un protocollo di recupero rapido (ERAS).",ax:"Panel multidisciplinare cinese",date:"set 2026",meta:"consensus Delphi modificato, panel multidisciplinare cinese · [V]",pmid:'42642184',doi:'10.7507/1002-1892.202606094',journal:"Chinese Journal of Reparative and Reconstructive Surgery",authors:"non riportati individualmente nei metadati PubMed di questa voce",design:"Consensus Delphi modificato costruito da un panel multidisciplinare cinese di esperti di chirurgia protesica: revisione della letteratura cinese e internazionale, bozza iniziale, due turni di questionario agli esperti e una discussione online conclusiva; consenso definito come accordo ≥85%, distinto in forte (95-100%), generale (90-94,9%) e moderato (85-89,9%).",pop:"Non applicabile: documento di consensus, non uno studio su una coorte di pazienti.",results:"Non riportati numeri di accordo per le singole raccomandazioni nell'abstract: il documento offre indicazioni su valutazione preoperatoria di precisione, imaging multimodale, selezione del paziente, disegno e impianto personalizzato, gestione perioperatoria, controllo del dolore, riabilitazione funzionale e follow-up a lungo termine.",concl:"Il panel conclude che questo consensus offre una guida pratica per standardizzare il percorso clinico della protesi ad alta conformità dentro un protocollo ERAS, per ottimizzare la gestione perioperatoria e il recupero funzionale.",limits:"Consensus di esperti, livello V: non uno studio con dati originali su pazienti · costruito su letteratura e pratica cinesi, la trasferibilità ad altri contesti sanitari non è discussa nell'abstract · la protesi «ad alta conformità personalizzata» è una categoria di impianto diversa dal sistema VELYS che utilizzi.",perte:"Non riguarda la piattaforma che usi né una protesi standard: qui la «alta conformità» è un impianto personalizzato per anatomia individuale, categoria diversa da VELYS. Resta rilevante come esempio di come la Cina stia standardizzando in modo strutturato i percorsi ERAS attorno alla protesi di ginocchio — un movimento su scala che vale la pena conoscere anche senza applicazione diretta alla tua pratica."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Robotic Surgery",h:"Robot senza immagini o laser: nella protesi l'allineamento non cambia",v:"In 259 protesi totali di ginocchio consecutive, l'assistenza robotica senza immagini preoperatorie non riduce ulteriormente l'errore di allineamento dell'asse meccanico rispetto alla sola guida laser, tranne in un piccolo sottogruppo di ginocchia molto varate.",ax:"Baek, Yoon, Park et al.",date:"set 2026",meta:"coorte comparativa monocentrica, 259 protesi (110 manuali, 99 guida laser, 50 robot senza immagini) · [III]",pmid:'42671670',doi:'10.1007/s11701-026-03895-4',journal:"Journal of Robotic Surgery",authors:"Baek NJ, Yoon JY, Park HS, Lee DH, Park J, Kim JB",design:"Studio comparativo monocentrico su 259 protesi totali di ginocchio primarie consecutive (2023-2025): 110 manuali, 99 con guida laser dell'asse meccanico, 50 con assistenza robotica senza immagini preoperatorie (imageless). Esito primario: errore assoluto dell'angolo anca-ginocchio-caviglia (HKA) postoperatorio. Abbinamento per punteggio di propensione 1:1 fra guida laser e manuale, e fra robot e guida laser, incluso un sottogruppo prespecificato di varo grave (≥10° preoperatorio).",pop:"259 protesi totali di ginocchio consecutive: 110 manuali, 99 guida laser, 50 robot senza immagini.",results:"Errore HKA medio assoluto: 2,20° (manuale), 1,19° (guida laser), 0,95° (robot); p<0,001 nel confronto complessivo. Dopo abbinamento per propensione, la guida laser ha un errore HKA inferiore alla tecnica manuale (-1,01°; IC 95% -1,38/-0,64; p<0,001). L'errore HKA non differisce tra robot e guida laser nella coorte completa (-0,03°; p=0,612). Nel sottogruppo di varo grave abbinato (n=16), il robot ha un errore coronale femorale inferiore (-0,86°; p corretto Holm=0,019), ma il risultato non resiste all'analisi di sensibilità con calibro più stretto. Il robot richiede 14,41 minuti in più di tempo operatorio aggiustato e costi diretti più alti (rapporto 1,208; IC 95% 1,146-1,274).",concl:"Gli autori concludono che, dopo abbinamento per propensione, la guida laser riduce l'errore di allineamento dell'intero arto rispetto alla tecnica manuale, mentre l'assistenza robotica senza immagini non mostra un vantaggio rilevabile sull'errore HKA dell'intero arto rispetto alla sola guida laser; nel sottogruppo esplorativo di varo grave il robot mostra un errore del componente femorale inferiore, ma il campione piccolo e la mancata conferma nell'analisi di sensibilità impongono cautela.",limits:"Studio comparativo osservazionale, monocentrico, non randomizzato · il sottogruppo di varo grave conta solo 16 coppie abbinate e il vantaggio del robot non persiste nell'analisi di sensibilità con calibro più stretto · il sistema robotico testato non è VELYS: è un diverso sistema senza immagini, quindi il risultato non si trasferisce automaticamente al tuo strumento.",perte:"Riguarda esattamente la categoria del tuo VELYS — l'assistenza robotica senza immagini preoperatorie — anche se il sistema testato è diverso. Il messaggio centrale per il colloquio con i pazienti: nell'allineamento dell'intero arto il robot senza immagini non batte in modo dimostrabile una guida laser molto più semplice ed economica, tranne forse nei casi di varo più grave, dove però il segnale è debole e non confermato nell'analisi di sensibilità."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"The Knee",h:"Nella protesi robotica, alzare la linea articolare mediale peggiora il risultato",v:"In 147 ginocchia operate di protesi robot-assistita con conservazione del crociato e allineamento funzionale, innalzare la linea articolare nel comparto mediale si associa a un punteggio funzionale a un anno peggiore rispetto a chi la mantiene o la abbassa leggermente.",ax:"Jung, Cha, Hwang, Kim",date:"set 2026",meta:"coorte retrospettiva monocentrica, 147 ginocchia · [III]",pmid:'42585985',doi:'10.1016/j.knee.2026.104594',journal:"The Knee",authors:"Jung HJ, Cha SH, Hwang J, Kim JI",design:"Studio retrospettivo monocentrico su 147 ginocchia sottoposte a protesi totale primaria con conservazione del crociato posteriore, robot-assistita, con allineamento funzionale. Altezza della linea articolare (distanza perpendicolare dall'asse transepicondilare al punto più distale dei condili femorali) misurata su TC pre- e postoperatoria; pazienti classificati in elevazione, neutro o depressione in base a una deviazione di 2 mm dalla linea nativa, separatamente per comparto mediale e laterale. Esiti riferiti dal paziente a 1 anno.",pop:"147 ginocchia, protesi totale primaria con conservazione del crociato e allineamento funzionale.",results:"La depressione media della linea articolare si verifica in entrambi i comparti, maggiore nel laterale (3,1±2,5 mm) che nel mediale (1,8±2,5 mm). Nel comparto mediale, il gruppo elevazione ha il punteggio Forgotten Joint Score-12 più basso fra i tre gruppi (differenza media 28,5 punti; d di Cohen 1,09). I cambiamenti della linea articolare laterale non sono significativamente associati agli esiti a 1 anno. L'asimmetria finale degli spazi articolari è comparabile fra i sottogruppi della linea mediale.",concl:"Gli autori concludono che, sebbene la depressione della linea articolare sia relativamente bene tollerata, un'elevazione della linea articolare mediale si associa a esiti riferiti dal paziente peggiori a 1 anno dopo protesi robot-assistita con conservazione del crociato e allineamento funzionale; un'elevazione mediale non necessaria andrebbe evitata.",limits:"Studio retrospettivo monocentrico, livello III, senza gruppo di controllo con allineamento meccanico classico · sistema robotico e criteri di allineamento funzionale specifici del centro, non necessariamente identici al tuo protocollo VELYS · follow-up limitato a 1 anno, nessun dato sulla sopravvivenza dell'impianto a lungo termine.",perte:"Diretto sulla tua pratica: protesi robot-assistita con conservazione del crociato e allineamento funzionale sono esattamente gli elementi che usi con VELYS. Il messaggio operativo — evitare un'elevazione non necessaria della linea articolare mediale quando si bilanciano gli spazi — è un promemoria intraoperatorio concreto, anche se il centro e il protocollo non sono identici al tuo."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Dopo l'osteotomia, la rotula si sposta meno dell'osso che la regge",v:"In 45 ginocchia operate di osteotomia tibiale alta ad apertura mediale, l'allineamento coronale dell'articolazione femoro-rotulea cambia meno dell'angolo di correzione osseo, con un impatto clinico e cartilagineo trascurabile.",ax:"Maeda, Kuriyama, Sakai et al.",date:"set 2026",meta:"serie di casi retrospettiva monocentrica, 45 ginocchia/39 pazienti · [IV]",pmid:'42712207',doi:'10.1002/arj.70533',journal:"Arthroscopy",authors:"Maeda T, Kuriyama S, Sakai S, Morita Y, Morita Y, Nishitani K, Nakamura S, Matsuda S",design:"Studio retrospettivo su pazienti sottoposti a osteotomia tibiale alta ad apertura mediale (2019-2022) con TC dell'intero arto pre- e postoperatoria. Allineamento coronale femoro-rotuleo misurato con gli angoli della cresta rotulea, del solco trocleare femorale, del quadricipite femorale e del tendine rotuleo. Punteggio KOOS pre- e postoperatorio (prima della rimozione dell'impianto) e grado ICRS della cartilagine femoro-rotulea su artroscopia primaria e second-look. Differenza minima clinicamente importante definita come metà della deviazione standard del cambiamento del punteggio.",pop:"45 ginocchia di 39 pazienti.",results:"Angolo di correzione coronale medio su TC postoperatoria: 9,3°. I cambiamenti degli indicatori di allineamento femoro-rotuleo sono significativamente più piccoli dell'angolo di correzione, con la cresta rotulea meno interessata del quadricipite femorale (3,0° contro 6,8°; p<0,001). Solo il punteggio KOOS per le attività della vita quotidiana diminuisce con l'aumento dell'angolo del tendine rotuleo (r=-0,333). Oltre il 70% dei pazienti raggiunge un miglioramento superiore alla differenza minima clinicamente importante nei sottopunteggi KOOS. Il grado ICRS della cartilagine rotulea peggiora leggermente (p=0,004), senza correlazioni significative fra il cambiamento del grado ICRS e i punteggi clinici.",concl:"Gli autori concludono che i cambiamenti dell'allineamento coronale femoro-rotuleo dopo osteotomia tibiale alta ad apertura mediale sono significativamente più piccoli dell'angolo di correzione osseo, in particolare per gli indicatori ossei, e che le correlazioni fra questi cambiamenti e i punteggi clinici o il danno cartilagineo femoro-rotuleo sul piano coronale sono trascurabili.",limits:"Livello IV, serie di casi retrospettiva monocentrica, senza gruppo di controllo · solo tecnica ad apertura mediale, non generalizzabile ad altre osteotomie · il peggioramento del grado ICRS rotuleo, seppur statisticamente significativo, non si traduce in una correlazione clinica misurabile nell'abstract.",perte:"Una rassicurazione operativa per la tua pratica di osteotomie correttive: il timore che correggere l'asse tibiale disturbi in modo rilevante l'articolazione femoro-rotulea non trova qui conferma clinica, anche se un piccolo peggioramento cartilagineo rotuleo va tenuto a mente e monitorato nel tempo."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"The Journal of Arthroplasty",h:"Nella protesi, piccoli cambi di slope tibiale non cambiano il risultato",v:"In 370 protesi totali postero-stabilizzate con almeno 4 anni di follow-up, né la direzione né l'ampiezza del cambiamento di slope tibiale posteriore si associano in modo clinicamente rilevante al risultato funzionale: conta più lo stato funzionale preoperatorio.",ax:"Altun, Ergişi, Özdemir et al.",date:"set 2026",meta:"coorte retrospettiva monocentrica, 370 pazienti, follow-up minimo 48 mesi · [III]",pmid:'42716147',doi:'10.1016/j.arth.2026.09.001',journal:"The Journal of Arthroplasty",authors:"Altun O, Ergişi Y, Özdemir E, Özihtiyar AA, Altıntaş M, Daşar U",design:"Studio di coorte retrospettivo monocentrico su 370 pazienti sottoposti a protesi totale di ginocchio primaria cementata postero-stabilizzata con un unico disegno di impianto, follow-up minimo 48 mesi. Slope tibiale posteriore (PTS) misurato pre- e postoperatorio su radiografie laterali standardizzate da due osservatori indipendenti in cieco. Cambiamento del PTS analizzato per direzione (diminuzione, neutro, aumento), ampiezza (≤3°, 4-9°, ≥10°) e per una soglia basata sul cambiamento medio assoluto (5,47°). Esiti: VAS, WOMAC, Knee Society Score, Oxford Knee Score, Forgotten Joint Score-12, range di movimento.",pop:"370 pazienti, età media 71 anni (range 55-90), follow-up medio 64,6 mesi (range 48-74).",results:"Tutti i punteggi riferiti dal paziente migliorano significativamente dopo l'intervento. Né la direzione né l'ampiezza del cambiamento di PTS si associano al dolore postoperatorio, agli esiti funzionali o al miglioramento clinico complessivo (tutti p>0,05). Un aumento del PTS si associa a un modesto aumento della flessione postoperatoria (0,53° per ogni grado di aumento; p<0,001), ma questo guadagno di movimento non si traduce in un miglioramento degli esiti riferiti dal paziente. Lo stato funzionale preoperatorio è il predittore più forte del risultato postoperatorio in tutte le analisi.",concl:"Gli autori concludono che, entro gli intervalli chirurgici accettati, i cambiamenti dello slope tibiale posteriore non hanno un impatto clinicamente rilevante sugli esiti funzionali dopo protesi postero-stabilizzata, e che il successo postoperatorio è guidato soprattutto dallo stato funzionale preoperatorio.",limits:"Studio retrospettivo monocentrico, livello III, un solo disegno di impianto postero-stabilizzato · non è il disegno con conservazione del crociato che potresti usare con VELYS · l'analisi copre solo gli intervalli chirurgici «accettati», non gli errori di slope più estremi.",perte:"Riguarda la protesi totale in generale, non specificamente il tuo sistema VELYS né necessariamente il disegno di impianto che usi (qui postero-stabilizzato). Il messaggio operativo resta utile: entro i margini chirurgici normali, piccole variazioni di slope tibiale non sembrano il fattore che decide il risultato — è lo stato funzionale di partenza del paziente a pesare di più."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"Archives of Orthopaedic and Trauma Surgery",h:"Il carico sulla rotula durante la protesi varia molto da un impianto all'altro",v:"Un registro di 291 protesi con misurazione intraoperatoria diretta del carico femoro-rotuleo mostra una variabilità individuale marcata, con un sottogruppo che supera un aumento cumulativo del 70%, più frequente nella protesi totale che nella sola resuperficializzazione femoro-rotulea.",ax:"Phillipson, Naybour, Watson et al.",date:"set 2026",meta:"studio di registro osservazionale descrittivo, 291 protesi · [IV]",pmid:'42714608',doi:'10.1007/s00402-026-06500-3',journal:"Archives of Orthopaedic and Trauma Surgery",authors:"Phillipson L, Naybour J, Watson A, London N, Barrett D",design:"Studio di registro osservazionale su misurazioni intraoperatorie del carico femoro-rotuleo (dispositivo Quadsense) raccolte prospetticamente in 291 interventi di protesi di ginocchio, prima e dopo l'impianto delle componenti di prova, nei comparti mediale, laterale, superiore e inferiore. Analisi descrittiva della distribuzione e della variabilità del cambiamento di carico per tipo di procedura (protesi totale vs resuperficializzazione femoro-rotulea isolata) e, solo per la protesi totale, per sistema di impianto; nessun test di ipotesi prespecificato, nessun aggiustamento per fattori di confondimento.",pop:"291 procedure di protesi di ginocchio (protesi totale e resuperficializzazione femoro-rotulea isolata).",results:"Il cambiamento cumulativo di carico femoro-rotuleo mostra una variabilità inter-individuale marcata: la maggior parte dei casi si concentra su piccoli cambiamenti percentuali, ma un sottogruppo distinto supera un aumento cumulativo del +70%. La protesi totale mostra una distribuzione più ampia e una frequenza osservata più alta di grandi aumenti rispetto alla resuperficializzazione isolata. L'analisi per sistema di impianto, limitata alla protesi totale, mostra differenze descrittive fra le coorti di impianto, con alcuni sistemi con una frequenza osservata più alta di grandi aumenti. La ridistribuzione del carico avviene soprattutto nei comparti laterale e superiore.",concl:"Gli autori concludono che la ridistribuzione intraoperatoria del carico femoro-rotuleo dopo protesi di ginocchio è molto variabile e differisce, in modo descrittivo, tra tipo di procedura e sistema di impianto, con un sottogruppo di pazienti che sperimenta grandi aumenti cumulativi soprattutto nei comparti laterale e superiore.",limits:"Disegno di registro osservazionale, nessun test di ipotesi prespecificato né aggiustamento per confondenti: le differenze fra impianti sono descrittive, non causali · gli specifici sistemi di impianto confrontati non sono nominati nell'abstract, quindi non si sa se VELYS/ATTUNE sia tra questi · nessun esito clinico riferito dal paziente collegato alle misure di carico in questo abstract.",perte:"Si collega al filone di overstuffing/tracking rotuleo emerso l'8 settembre (Journal of Robotic Surgery, sistema MAKO): qui la misura è diretta, intraoperatoria e su scala di registro, e mostra che il carico femoro-rotuleo può variare enormemente da paziente a paziente e, descrittivamente, da impianto a impianto — un ulteriore richiamo a controllare il tracking rotuleo caso per caso, non solo l'allineamento generale, anche senza sapere se VELYS/ATTUNE sia tra i sistemi confrontati."},{n:8,mono:"m-gray",dot:"green",sec:"res",j:"Clinical Biomechanics",h:"Un biofeedback in tempo reale riduce il carico cumulativo dopo il LCA",v:"In 39 pazienti 6-12 mesi dopo la ricostruzione del LCA, un biofeedback in tempo reale che aumenta il picco di forza di reazione al terreno durante il cammino riduce il carico cumulativo sull'arto operato, senza cambiare in modo significativo i momenti articolari al ginocchio.",ax:"Buck, Armitano-Lago, Bjornsen et al.",date:"set 2026",meta:"studio sperimentale controllato, 39 pazienti · [II]",pmid:'42710345',doi:'10.1016/j.clinbiomech.2026.106949',journal:"Clinical Biomechanics",authors:"Buck AN, Armitano-Lago C, Bjornsen ES, Davis-Wilson H, Evans-Pickett A, Munsch AE, Schwartz TA, Franz JR, Pietrosimone B",design:"Studio sperimentale su 39 pazienti 6-12 mesi dopo ricostruzione del LCA, ciascuno sottoposto a due condizioni di biofeedback del cammino in tempo reale (RTGBF) su tapis roulant strumentato: una condizione «dinamica» che segnala un aumento del 5% del peso corporeo nel picco di forza di reazione verticale al terreno (vGRF), una condizione «sostenuta» che segnala una diminuzione del 5%. 3000 passi per condizione, a velocità autoselezionata. Confronto dell'impulso di vGRF in fase di appoggio e degli impulsi assoluti dei momenti articolari al ginocchio sul piano sagittale e frontale.",pop:"39 partecipanti (46% uomini), età 21±4 anni, 6-12 mesi dopo ricostruzione primaria del LCA.",results:"L'impulso di vGRF è significativamente più basso durante il carico dinamico rispetto al carico sostenuto (0,51±0,07 contro 0,54±0,06 peso corporeo×secondi; p=0,03). Nessuna differenza statisticamente significativa negli impulsi assoluti dei momenti al ginocchio sul piano sagittale (0,15±0,04 contro 0,17±0,10 Nm/kg×s) o frontale (0,07±0,04 contro 0,07±0,04 Nm/kg×s).",concl:"Gli autori concludono che indurre un aumento del picco di forza di reazione al terreno tramite biofeedback in tempo reale riduce il carico compressivo cumulativo sull'arto senza aumentare in modo rilevabile il carico impulsivo complessivo articolare al ginocchio a ogni passo, un dato utile per i futuri studi di re-training del cammino.",limits:"Nessuna soglia clinicamente rilevante stabilita per la differenza di impulso vGRF osservata: la sua importanza clinica resta sconosciuta · popolazione giovane (21±4 anni) e a breve distanza dalla ricostruzione (6-12 mesi) · l'abstract non riporta il tipo di innesto utilizzato dai partecipanti.",perte:"Tocca la stessa area della tensione T3 da un angolo tecnico diverso: uno strumento di biofeedback che modula il carico del cammino, non solo lo misura, e mostra che si può aumentare il picco di forza al passo senza necessariamente aumentare il carico complessivo articolare — un dato preliminare, ma rilevante se mai introdurrai un re-training del cammino guidato da biofeedback nella riabilitazione tardiva dei tuoi operati di LCA."}];
var SUGGQ=[{"k": "kol", "n": "Joong Il Kim", "w": "Kangnam Sacred Heart Hospital, Hallym University College of Medicine, Seoul (Corea del Sud)", "r": "Autore corrispondente dello studio di oggi su linea articolare e protesi robotica con conservazione del crociato e allineamento funzionale: corrispondenza tecnica diretta con la tua pratica di protesi robot-assistita VELYS con allineamento funzionale. Copre inoltre il «buco dichiarato» del mondo orientale — la Corea del Sud non era mai comparsa finora nelle proposte. Sostituisce la proposta invariata di Ryan M. Degen (9 settembre)."}];
var BRIEF_TEXT="Otto lavori oggi, nessuno rosso, uno arancione. Il lavoro arancione è anche quello scelto come lavoro del giorno: una meta-analisi di 43 studi su oltre diciassettemila pazienti mostra che il test del salto monopodalico, il modo più comune per decidere se un tuo paziente può rientrare allo sport dopo la ricostruzione del crociato, si associa davvero a un rientro più probabile — ma non protegge in modo dimostrabile dal reinfortunio. Superare la soglia del 90% di simmetria nel salto triplo in distanza semplice si associa anzi a un rischio più alto, non più basso, anche se l'intervallo è così vicino all'unità da pesare poco nella pratica. Non tocca il tuo innesto né il rinforzo laterale che esegui sempre, ma con quasi diciottomila pazienti in pooling è il segnale più solido finora sulla tensione che tieni aperta da luglio: un criterio motorio isolato non basta a garantire la sicurezza del rientro.\n\nSulla stessa area, un piccolo studio americano mostra che un biofeedback in tempo reale, che aumenta il picco di forza al passo durante il cammino, riduce il carico cumulativo sull'arto operato senza aumentare i momenti articolari al ginocchio — un primo strumento tecnico, non ancora validato su esiti clinici, per modulare il carico oltre la sola misura della simmetria.\n\nIl resto della giornata è tutto verde, senza conflitti con la tua pratica. Un consensus cinese unifica il percorso di recupero rapido per una protesi personalizzata ad alta conformità — un impianto diverso da VELYS, ma un esempio di come si stia standardizzando il percorso perioperatorio attorno alla protesi di ginocchio. Due lavori coreani toccano più da vicino il tuo sistema: un confronto fra robot senza immagini e semplice guida laser non trova un vantaggio dimostrabile del robot sull'allineamento dell'intero arto, tranne un segnale debole nei casi di varo più grave; un secondo mostra che, nella protesi robotica con conservazione del crociato e allineamento funzionale, alzare la linea articolare nel comparto mediale peggiora il punteggio funzionale a un anno — un promemoria intraoperatorio concreto.\n\nSull'osteotomia, un lavoro giapponese rassicura: correggere l'asse tibiale sposta l'allineamento della rotula meno dell'angolo di correzione osseo, con un impatto clinico trascurabile. Due lavori toccano invece la protesi in generale: uno turco su 370 pazienti non trova alcun legame clinicamente rilevante tra piccoli cambi di slope tibiale e risultato funzionale dopo protesi postero-stabilizzata; un registro britannico misura direttamente, per la prima volta su questa scala, quanto varia il carico sulla rotula durante l'intervento — con un sottogruppo di pazienti che supera un aumento del 70%, più spesso nella protesi totale che nella sola resuperficializzazione.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi partiamo dal lavoro arancione, che è anche il lavoro scelto: una meta-analisi enorme sul test del salto dopo la ricostruzione del crociato."}, {"chi": "B", "t": "Quello che si usa per decidere se un paziente può tornare a giocare?"}, {"chi": "A", "t": "Esatto. 43 studi, oltre 17.000 pazienti: superarlo si associa a un rientro più probabile."}, {"chi": "B", "t": "Ma non protegge dal reinfortunio, giusto?"}, {"chi": "A", "t": "Proprio così. In un test specifico il rischio di reinfortunio risulta anzi un po' più alto, non più basso — anche se il margine è piccolo."}, {"chi": "B", "t": "Quindi il test da solo non basta per decidere il rientro."}, {"chi": "A", "t": "È il punto centrale della tensione che tengo aperta da luglio. E oggi un secondo studio, più piccolo, va nella stessa direzione: un biofeedback in tempo reale sul cammino riduce il carico sulla gamba operata."}, {"chi": "B", "t": "Passiamo alla protesi robotica: che novità ci sono?"}, {"chi": "A", "t": "Due lavori coreani. Il primo: un robot senza immagini non batte in modo dimostrabile una semplice guida laser sull'allineamento della gamba."}, {"chi": "B", "t": "E il tuo VELYS dove si colloca?"}, {"chi": "A", "t": "Nella stessa categoria — senza immagini — anche se il sistema testato è diverso. Il secondo studio è più operativo: alzare troppo la linea articolare sul lato interno del ginocchio, nella protesi robotica, peggiora il risultato a un anno."}, {"chi": "B", "t": "Un promemoria intraoperatorio, quindi."}, {"chi": "A", "t": "Esatto. E per chiudere, due buone notizie tecniche: correggere l'asse della tibia con un'osteotomia disturba la rotula molto meno di quanto si pensi; e un registro britannico mostra quanto vari, da paziente a paziente, il carico sulla rotula durante la protesi — un motivo in più per controllarlo caso per caso."}];
